import pytest
from flask import Flask
from werkzeug.test import EnvironBuilder

def test_open_reuses_preserved_contexts_enter_once():
    app = Flask(__name__)

    @app.route('/')
    def index():
        return 'OK'

    client = app.test_client()

    enter_counter = {'n': 0}
    exit_counter = {'n': 0}

    class DummyCM:
        def __enter__(self):
            enter_counter['n'] += 1
            return self

        def __exit__(self, exc_type, exc, tb):
            exit_counter['n'] += 1
            return False

    cm = DummyCM()
    client._new_contexts = [cm]

    response = client.open('/')
    assert response.status_code == 200
    assert enter_counter['n'] == 1
    assert exit_counter['n'] == 0
    assert client._new_contexts == []

def test_open_sets_json_module_on_response():
    app = Flask(__name__)

    @app.route('/')
    def index():
        return 'OK'

    client = app.test_client()
    response = client.open('/')

    # The Open method should assign the app's json provider to the response
    assert hasattr(response, 'json_module')
    assert response.json_module is app.json

def test_open_with_environbuilder_argument():
    app = Flask(__name__)

    @app.route('/')
    def index():
        return 'OK'

    client = app.test_client()

    builder = EnvironBuilder(path='/', method='GET', app=app)
    response = client.open(builder)
    assert response.status_code == 200

