import click
import pytest
from flask import Flask
from flask.cli import AppGroup

def test_wrap_for_ctx_true_invokes_within_app_context(monkeypatch):
    group = AppGroup('test')
    group.wrap_for_ctx = True

    results = {'executed': False, 'wrapped': False}

    def f():
        results['executed'] = True

    def fake_with_appcontext(g):
        def wrapped(*args, **kwargs):
            results['wrapped'] = True
            return g(*args, **kwargs)
        return wrapped

    monkeypatch.setattr('flask.cli.with_appcontext', fake_with_appcontext)

    decorator = group.command()
    cmd = decorator(f)

    assert isinstance(cmd, click.Command)
    assert results['wrapped'] is True

    cmd.callback()
    assert results['executed'] is True

def test_wrap_for_ctx_false_does_not_wrap(monkeypatch):
    group = AppGroup('test')
    group.wrap_for_ctx = False

    results = {'executed': False, 'wrapped': False}

    def f():
        results['executed'] = True

    def fake_with_appcontext(g):
        def wrapped(*args, **kwargs):
            results['wrapped'] = True
            return g(*args, **kwargs)
        return wrapped

    monkeypatch.setattr('flask.cli.with_appcontext', fake_with_appcontext)

    decorator = group.command()
    cmd = decorator(f)

    assert isinstance(cmd, click.Command)
    assert results['wrapped'] is False

    cmd.callback()
    assert results['executed'] is True

