import unittest
from flask.json.tag import TagDict
from unittest.mock import MagicMock

class TestTagDictToJson(unittest.TestCase):
    def setUp(self):
        self.serializer_mock = MagicMock()
        self.serializer_mock.tag.return_value = "tagged_value"
        self.tag_dict = TagDict()
        self.tag_dict.serializer = self.serializer_mock

    def test_to_json_single_key_value(self):
        value = {"key": "value"}
        result = self.tag_dict.to_json(value)
        self.assertEqual(result, {"key__": "tagged_value"})
        self.serializer_mock.tag.assert_called_once_with("value")

    def test_to_json_empty_dict(self):
        with self.assertRaises(StopIteration):
            self.tag_dict.to_json({})

    def test_to_json_multiple_keys(self):
        value = {"key1": "value1", "key2": "value2"}
        result = self.tag_dict.to_json(value)
        # Only the first key is used
        self.assertEqual(result, {"key1__": "tagged_value"})
        self.serializer_mock.tag.assert_called_once_with("value1")

    def test_to_json_nested_value(self):
        value = {"key": {"nested_key": "nested_value"}}
        result = self.tag_dict.to_json(value)
        self.assertEqual(result, {"key__": "tagged_value"})
        self.serializer_mock.tag.assert_called_once_with({"nested_key": "nested_value"})

    def test_to_json_none_value(self):
        value = {"key": None}
        result = self.tag_dict.to_json(value)
        self.assertEqual(result, {"key__": "tagged_value"})
        self.serializer_mock.tag.assert_called_once_with(None)

if __name__ == '__main__':
    unittest.main()

