import unittest
import uuid
import datetime
from flask.json.tag import TaggedJSONSerializer, TagDict, PassDict, TagTuple, PassList, TagBytes, TagMarkup, TagUUID, TagDateTime

class TestTaggedJSONSerializerTag(unittest.TestCase):

    def setUp(self):
        self.serializer = TaggedJSONSerializer()

    def test_tag_dict(self):
        value = {"key": "value"}
        result = self.serializer.tag(value)
        expected = {" __flask": "di", "v": value}
        self.assertEqual(result, expected)

    def test_tag_dict_subclass(self):
        class CustomDict(dict):
            pass
        value = CustomDict(key="value")
        result = self.serializer.tag(value)
        # TagDict checks for isinstance(dict), so CustomDict should be tagged
        self.assertIn(" __flask", result)
        self.assertEqual(result[" __flask"], "di")

    def test_tag_pass_dict(self):
        # PassDict handles dict-like objects (usually session objects) that are not strictly dicts
        # but standard dicts are handled by TagDict first due to order.
        # To test PassDict specifically, we need a value that is dict-like but fails TagDict check
        # However, since TagDict uses isinstance(value, dict), any dict subclass is caught.
        # PassDict is there for specific objects in Flask context.
        # Given the default_tags list order: TagDict, PassDict...
        # Standard dicts hit TagDict.
        pass

    def test_tag_tuple(self):
        value = (1, 2, 3)
        result = self.serializer.tag(value)
        expected = {" __flask": "tu", "v": [1, 2, 3]}
        self.assertEqual(result, expected)

    def test_tag_list(self):
        # PassList is used for lists, but usually returns the list itself or a specific representation
        # In flask/json/tag.py, PassList check returns True for lists, and tag returns value.
        value = [1, 2, 3]
        result = self.serializer.tag(value)
        self.assertEqual(result, value)

    def test_tag_bytes(self):
        value = b"hello"
        result = self.serializer.tag(value)
        expected = {" __flask": "by", "v": value.decode("utf-8")}
        self.assertEqual(result, expected)

    def test_tag_uuid(self):
        value = uuid.uuid4()
        result = self.serializer.tag(value)
        expected = {" __flask": "ui", "v": str(value)}
        self.assertEqual(result, expected)

    def test_tag_datetime(self):
        value = datetime.datetime(2023, 1, 1, 12, 0, 0)
        result = self.serializer.tag(value)
        expected = {" __flask": "dt", "v": value.isoformat()}
        self.assertEqual(result, expected)

    def test_tag_untagged_value(self):
        # Test a value that doesn't match any tags
        value = "simple string"
        result = self.serializer.tag(value)
        self.assertEqual(result, value)

    def test_tag_none(self):
        # Test None value
        result = self.serializer.tag(None)
        self.assertIsNone(result)

    def test_tag_int(self):
        # Test integer
        value = 42
        result = self.serializer.tag(value)
        self.assertEqual(result, value)

    def test_tag_order(self):
        # Verify that TagDict is checked before PassDict
        # If we pass a dict, it should be tagged with "di" (TagDict), not ignored by PassDict
        value = {"a": 1}
        result = self.serializer.tag(value)
        self.assertEqual(result.get(" __flask"), "di")

    def test_tag_empty_dict(self):
        value = {}
        result = self.serializer.tag(value)
        expected = {" __flask": "di", "v": {}}
        self.assertEqual(result, expected)

    def test_tag_empty_tuple(self):
        value = ()
        result = self.serializer.tag(value)
        expected = {" __flask": "tu", "v": []}
        self.assertEqual(result, expected)

    def test_tag_empty_list(self):
        value = []
        result = self.serializer.tag(value)
        self.assertEqual(result, [])

if __name__ == "__main__":
    unittest.main()

