import unittest
from flask.sansio.blueprints import Blueprint


class TestTeardownAppRequest(unittest.TestCase):

    def test_teardown_app_request_decorator_behavior(self):
        """Test that the decorator returns the original function."""
        bp = Blueprint("test", __name__)

        def dummy_teardown(exception):
            pass

        result = bp.teardown_app_request(dummy_teardown)
        self.assertIs(result, dummy_teardown)

    def test_teardown_app_request_registers_deferred_function(self):
        """Test that the method registers a deferred function."""
        bp = Blueprint("test", __name__)
        initial_deferred_count = len(bp.deferred_functions)

        def dummy_teardown(exception):
            pass

        bp.teardown_app_request(dummy_teardown)

        # Assert that a deferred function has been added
        self.assertEqual(len(bp.deferred_functions), initial_deferred_count + 1)

    def test_teardown_app_request_deferred_execution_logic(self):
        """Test that executing the deferred function modifies the app's teardown_request_funcs."""
        bp = Blueprint("test", __name__)

        def dummy_teardown(exception):
            pass

        bp.teardown_app_request(dummy_teardown)

        # Mock the state object passed to the deferred function
        # The Blueprint expects the state object to have an 'app' attribute
        class MockState:
            def __init__(self):
                self.app = MockApp()

        class MockApp:
            def __init__(self):
                self.teardown_request_funcs = {}

        state = MockState()

        # The deferred function is the last item in the list
        deferred_func = bp.deferred_functions[-1]

        # Execute the deferred function
        deferred_func(state)

        # Verify that the app's teardown_request_funcs[None] list contains the function
        self.assertIn(None, state.app.teardown_request_funcs)
        self.assertIn(dummy_teardown, state.app.teardown_request_funcs[None])

    def test_teardown_app_request_appends_to_existing_list(self):
        """Test that the function is appended to an existing list of teardown functions."""
        bp = Blueprint("test", __name__)

        def dummy_teardown_1(exception):
            pass

        def dummy_teardown_2(exception):
            pass

        bp.teardown_app_request(dummy_teardown_1)
        bp.teardown_app_request(dummy_teardown_2)

        class MockState:
            def __init__(self):
                self.app = MockApp()

        class MockApp:
            def __init__(self):
                self.teardown_request_funcs = {}

        state = MockState()

        # Execute both deferred functions
        for deferred_func in bp.deferred_functions:
            deferred_func(state)

        self.assertIn(dummy_teardown_1, state.app.teardown_request_funcs[None])
        self.assertIn(dummy_teardown_2, state.app.teardown_request_funcs[None])

if __name__ == '__main__':
    unittest.main()

