import unittest
from unittest.mock import MagicMock, patch

import click
from flask.cli import AppGroup


class TestAppGroupDecorator(unittest.TestCase):
    def setUp(self):
        self.app_group = AppGroup(name='test_group')

    @patch('flask.cli.with_appcontext')
    @patch.object(click.Group, 'command')
    def test_decorator_with_appcontext(self, mock_super_command, mock_with_appcontext):
        """Test the decorator logic when wrap_for_ctx is True."""
        mock_func = MagicMock()
        mock_wrapped_func = MagicMock()
        mock_with_appcontext.return_value = mock_wrapped_func

        def super_decorator(f):
            return f
        mock_super_command.return_value = super_decorator

        # Execute the decorator logic with wrap_for_ctx=True
        args = []
        kwargs = {}
        wrap_for_ctx = True

        def decorator(f):
            if wrap_for_ctx:
                f = with_appcontext(f)
            return super(AppGroup, self.app_group).command(*args, **kwargs)(f)

        result = decorator(mock_func)

        # Verify with_appcontext was called with the function
        mock_with_appcontext.assert_called_once_with(mock_func)
        # Verify the super command was called
        self.assertTrue(mock_super_command.called)

    @patch('flask.cli.with_appcontext')
    @patch.object(click.Group, 'command')
    def test_decorator_without_appcontext(self, mock_super_command, mock_with_appcontext):
        """Test the decorator logic when wrap_for_ctx is False."""
        mock_func = MagicMock()

        def super_decorator(f):
            return f
        mock_super_command.return_value = super_decorator

        # Execute the decorator logic with wrap_for_ctx=False
        args = []
        kwargs = {}
        wrap_for_ctx = False

        def decorator(f):
            if wrap_for_ctx:
                f = with_appcontext(f)
            return super(AppGroup, self.app_group).command(*args, **kwargs)(f)

        result = decorator(mock_func)

        # Verify with_appcontext was NOT called
        mock_with_appcontext.assert_not_called()
        # Verify the super command was called
        self.assertTrue(mock_super_command.called)

    def test_decorator_returns_click_command(self):
        """Test that the command creation logic returns a valid Click Command."""
        # Using the standard .command() interface which uses the same internal logic
        @self.app_group.command()
        def my_command():
            click.echo("Hello")

        self.assertIsInstance(my_command, click.Command)

    def test_decorator_passes_args_and_kwargs(self):
        """Test that args and kwargs are passed to super().command."""
        test_help = "Custom help message"
        test_name = "custom_name"

        with patch.object(click.Group, 'command') as mock_super_command:
            mock_command = MagicMock(spec=click.Command)
            # Mock super().command to return a function that acts as the decorator
            mock_super_command.return_value = lambda f: mock_command

            # Simulate the logic where the decorator factory captures args/kwargs
            args = []
            kwargs = {'help': test_help}
            wrap_for_ctx = False

            def decorator(f):
                if wrap_for_ctx:
                    f = with_appcontext(f)
                return super(AppGroup, self.app_group).command(*args, **kwargs)(f)

            # Apply the decorator
            result = decorator(lambda: None)

            # Verify super().command was called
            mock_super_command.assert_called_once()
            # Click.Group.command passes the captured kwargs as attributes
            # We call super(AppGroup, self).command(*args, **kwargs)
            # In the mock, check if kwargs were passed
            call_args, call_kwargs = mock_super_command.call_args
            self.assertEqual(call_kwargs.get('help'), test_help)
            self.assertEqual(result, mock_command)

