import pytest
import click
from click.testing import CliRunner, Result
from flask import Flask
from flask.cli import ScriptInfo
from flask.testing import FlaskCliRunner
from unittest.mock import Mock, patch, MagicMock


class TestFlaskCliRunnerInvoke:
    """Test cases for FlaskCliRunner.invoke method"""

    @pytest.fixture
    def app(self):
        """Create a Flask app for testing"""
        app = Flask(__name__)
        app.config['TESTING'] = True
        return app

    @pytest.fixture
    def cli_runner(self, app):
        """Create a FlaskCliRunner instance"""
        return FlaskCliRunner(app)

    @pytest.fixture
    def mock_cli(self):
        """Create a mock CLI command"""
        mock_cmd = Mock(spec=click.Command)
        mock_cmd.name = "test_command"
        return mock_cmd

    def test_invoke_with_default_cli(self, cli_runner, app):
        """Test invoke with default CLI (app.cli)"""
        # Create a simple command for the app's CLI
        @app.cli.command("test")
        def test_command():
            click.echo("Test command executed")

        result = cli_runner.invoke(args=["test"])

        assert isinstance(result, Result)
        assert result.exit_code == 0
        assert "Test command executed" in result.output

    def test_invoke_with_custom_cli(self, cli_runner, mock_cli):
        """Test invoke with custom CLI command"""
        def callback():
            click.echo("Custom CLI executed")

        mock_cli.callback = callback
        mock_cli.invoke = Mock(return_value=Result(runner=cli_runner, exit_code=0, output_bytes=b"Custom CLI executed\n"))

        result = cli_runner.invoke(cli=mock_cli, args=[])

        assert isinstance(result, Result)
        assert result.exit_code == 0

    def test_invoke_with_args(self, cli_runner, app):
        """Test invoke with command arguments"""
        @app.cli.command("echo")
        @click.argument("message")
        def echo_command(message):
            click.echo(f"Message: {message}")

        result = cli_runner.invoke(args=["echo", "Hello World"])

        assert result.exit_code == 0
        assert "Message: Hello World" in result.output

    def test_invoke_with_obj_kwarg_provided(self, cli_runner, app):
        """Test invoke when obj kwarg is already provided"""
        custom_obj = ScriptInfo(create_app=lambda: Flask("custom"))

        @app.cli.command("check-obj")
        @click.pass_context
        def check_obj_command(ctx):
            assert ctx.obj is custom_obj
            click.echo("Custom obj used")

        result = cli_runner.invoke(args=["check-obj"], obj=custom_obj)

        assert result.exit_code == 0
        assert "Custom obj used" in result.output

    def test_invoke_with_additional_kwargs(self, cli_runner, app):
        """Test invoke with additional keyword arguments"""
        @app.cli.command("test-kwargs")
        def test_kwargs_command():
            click.echo("Kwargs test")

        result = cli_runner.invoke(
            args=["test-kwargs"],
            catch_exceptions=False,
            color=True
        )

        assert result.exit_code == 0
        assert "Kwargs test" in result.output

    def test_invoke_error_case(self, cli_runner, app):
        """Test invoke with command that raises an exception"""
        @app.cli.command("error")
        def error_command():
            raise ValueError("Test error")

        result = cli_runner.invoke(args=["error"])

        # The exact behavior depends on CliRunner's configuration
        # but it should handle the exception
        assert result is not None

    def test_invoke_with_empty_args(self, cli_runner, app):
        """Test invoke with empty args list"""
        @app.cli.command("empty")
        def empty_command():
            click.echo("Empty args command")

        result = cli_runner.invoke(args=[])

        # Empty args should show help or similar
        assert isinstance(result, Result)

    def test_invoke_super_method_called(self, cli_runner, app):
        """Test that super().invoke is called with correct parameters"""
        with patch.object(CliRunner, 'invoke') as mock_super_invoke:
            mock_result = Result(runner=cli_runner, exit_code=0, output_bytes=b"Mocked\n")
            mock_super_invoke.return_value = mock_result

            @app.cli.command("test")
            def test_command():
                click.echo("Test")

            result = cli_runner.invoke(args=["test"], extra_kwarg="value")

            # Check that super().invoke was called
            mock_super_invoke.assert_called_once()

            # First arg should be the CLI command
            call_args = mock_super_invoke.call_args
            assert call_args[0][0] == app.cli

            # Second arg should be the args
            assert call_args[0][1] == ["test"]

            # kwargs should contain obj and extra_kwarg
            assert "obj" in call_args[1]
            assert isinstance(call_args[1]["obj"], ScriptInfo)
            assert call_args[1]["extra_kwarg"] == "value"

    def test_invoke_with_none_args(self, cli_runner, app):
        """Test invoke with None args"""
        @app.cli.command("none-args")
        def none_args_command():
            click.echo("None args handled")

        result = cli_runner.invoke(args=None)

        # None args should be handled gracefully
        assert isinstance(result, Result)

    def test_scriptinfo_creation(self, cli_runner, app):
        """Test that ScriptInfo is created with correct create_app function"""
        @app.cli.command("check-app")
        @click.pass_context
        def check_app_command(ctx):
            # Verify the ScriptInfo creates the correct app
            script_info = ctx.obj
            created_app = script_info.create_app()
            assert created_app is app
            click.echo("App verified")

        result = cli_runner.invoke(args=["check-app"])

        assert result.exit_code == 0
        assert "App verified" in result.output

