import pytest
from flask.json.tag import TagDict

class TestToJson:
    def setup_method(self):
        """Setup a serializer mock with tag method for testing."""
        class MockSerializer:
            def __init__(self):
                self.tag_calls = []

            def tag(self, value):
                self.tag_calls.append(value)
                return f"serialized_{value}"

        self.mock_serializer = MockSerializer()
        self.tag_dict = TagDict()
        self.tag_dict.serializer = self.mock_serializer

    def test_basic_dictionary_conversion(self):
        """Test with a normal dictionary containing one key-value pair."""
        input_dict = {"name": "John"}
        result = self.tag_dict.to_json(input_dict)

        assert result == {"name__": "serialized_John"}
        assert self.mock_serializer.tag_calls == ["John"]

    def test_dictionary_with_multiple_items(self):
        """Test with dictionary having multiple items - should only serialize first."""
        input_dict = {"name": "John", "age": 30, "city": "New York"}
        result = self.tag_dict.to_json(input_dict)

        # Should only serialize the first key-value pair
        assert result == {"name__": "serialized_John"}
        assert self.mock_serializer.tag_calls == ["John"]

    def test_dictionary_with_complex_values(self):
        """Test with dictionary containing complex values."""
        input_dict = {"data": {"nested": "value"}}
        result = self.tag_dict.to_json(input_dict)

        assert result == {"data__": "serialized_{'nested': 'value'}"}
        assert self.mock_serializer.tag_calls == [{"nested": "value"}]

    def test_dictionary_with_numeric_values(self):
        """Test with numeric values."""
        input_dict = {"count": 42}
        result = self.tag_dict.to_json(input_dict)

        assert result == {"count__": "serialized_42"}
        assert self.mock_serializer.tag_calls == [42]

    def test_dictionary_with_boolean_values(self):
        """Test with boolean values."""
        input_dict = {"active": True}
        result = self.tag_dict.to_json(input_dict)

        assert result == {"active__": "serialized_True"}
        assert self.mock_serializer.tag_calls == [True]

    def test_dictionary_with_list_values(self):
        """Test with list values."""
        input_dict = {"items": [1, 2, 3]}
        result = self.tag_dict.to_json(input_dict)

        assert result == {"items__": "serialized_[1, 2, 3]"}
        assert self.mock_serializer.tag_calls == [[1, 2, 3]]

    def test_dictionary_with_empty_string_key(self):
        """Test with empty string as key."""
        input_dict = {"": "empty key value"}
        result = self.tag_dict.to_json(input_dict)

        assert result == {"__": "serialized_empty key value"}
        assert self.mock_serializer.tag_calls == ["empty key value"]

    def test_dictionary_with_special_characters_key(self):
        """Test with special characters in key."""
        input_dict = {"key-with-dash": "value"}
        result = self.tag_dict.to_json(input_dict)

        assert result == {"key-with-dash__": "serialized_value"}
        assert self.mock_serializer.tag_calls == ["value"]

