import pytest
from flask.sansio.scaffold import setupmethod
from typing import Callable, Any
import functools

class MockScaffold:
    """Mock class to simulate the Scaffold behavior for testing."""

    def __init__(self, setup_finished: bool = False):
        self.setup_finished = setup_finished
        self._check_setup_finished_called = False
        self._check_setup_finished_name = None

    def _check_setup_finished(self, method_name: str) -> None:
        self._check_setup_finished_called = True
        self._check_setup_finished_name = method_name
        if self.setup_finished:
            raise RuntimeError(f"Setup already finished when calling {method_name}")

    def method_without_setup(self, *args: Any, **kwargs: Any) -> Any:
        """A method that doesn't require setup checking."""
        return (args, kwargs)

class TestSetupMethod:
    """Test class for the setupmethod decorator."""

    def test_decorator_preserves_metadata(self) -> None:
        """Test that the decorator preserves the original function's metadata."""

        @setupmethod
        def original_func(scaffold: MockScaffold, x: int, y: int) -> int:
            """Original function docstring."""
            return x + y

        assert original_func.__name__ == "original_func"
        assert original_func.__doc__ == "Original function docstring."
        assert callable(original_func)

    def test_setup_check_called_before_execution(self) -> None:
        """Test that _check_setup_finished is called before the wrapped function executes."""

        @setupmethod
        def test_method(scaffold: MockScaffold, value: int) -> int:
            return value * 2

        mock_scaffold = MockScaffold(setup_finished=False)
        result = test_method(mock_scaffold, 5)

        assert mock_scaffold._check_setup_finished_called
        assert mock_scaffold._check_setup_finished_name == "test_method"
        assert result == 10

    def test_setup_check_with_positional_args(self) -> None:
        """Test that the decorator works with various positional arguments."""

        @setupmethod
        def multi_arg_method(scaffold: MockScaffold, a: int, b: str, c: float) -> tuple:
            return (a, b, c)

        mock_scaffold = MockScaffold(setup_finished=False)
        result = multi_arg_method(mock_scaffold, 1, "test", 3.14)

        assert mock_scaffold._check_setup_finished_called
        assert result == (1, "test", 3.14)

    def test_setup_check_with_keyword_args(self) -> None:
        """Test that the decorator works with keyword arguments."""

        @setupmethod
        def kwarg_method(scaffold: MockScaffold, *, name: str, age: int) -> dict:
            return {"name": name, "age": age}

        mock_scaffold = MockScaffold(setup_finished=False)
        result = kwarg_method(mock_scaffold, name="Alice", age=30)

        assert mock_scaffold._check_setup_finished_called
        assert result == {"name": "Alice", "age": 30}

    def test_setup_check_with_mixed_args(self) -> None:
        """Test that the decorator works with mixed positional and keyword arguments."""

        @setupmethod
        def mixed_method(scaffold: MockScaffold, x: int, y: int, *, multiplier: int = 1) -> int:
            return (x + y) * multiplier

        mock_scaffold = MockScaffold(setup_finished=False)
        result = mixed_method(mock_scaffold, 3, 4, multiplier=2)

        assert mock_scaffold._check_setup_finished_called
        assert result == 14

    def test_setup_finished_raises_exception(self) -> None:
        """Test that when setup is finished, the check raises an exception."""

        @setupmethod
        def failing_method(scaffold: MockScaffold) -> None:
            pass

        mock_scaffold = MockScaffold(setup_finished=True)

        with pytest.raises(RuntimeError) as exc_info:
            failing_method(mock_scaffold)

        assert mock_scaffold._check_setup_finished_called
        assert "Setup already finished when calling failing_method" in str(exc_info.value)

    def test_decorator_works_with_class_methods(self) -> None:
        """Test that the decorator can be applied to class methods."""

        class TestClass:
            @setupmethod
            def instance_method(self, scaffold: MockScaffold, value: str) -> str:
                return f"Processed: {value}"

        test_instance = TestClass()
        mock_scaffold = MockScaffold(setup_finished=False)
        result = test_instance.instance_method(mock_scaffold, "test")

        assert mock_scaffold._check_setup_finished_called
        assert mock_scaffold._check_setup_finished_name == "instance_method"
        assert result == "Processed: test"

    def test_decorator_preserves_signature(self) -> None:
        """Test that the decorated function preserves the original signature."""

        @setupmethod
        def complex_signature(scaffold: MockScaffold, a: int, b: int = 10, *args: Any, c: str = "default", **kwargs: Any) -> dict:
            return {"a": a, "b": b, "args": args, "c": c, "kwargs": kwargs}

        mock_scaffold = MockScaffold(setup_finished=False)

        # Test with various argument combinations
        result1 = complex_signature(mock_scaffold, 1)
        assert result1["a"] == 1
        assert result1["b"] == 10
        assert result1["c"] == "default"

        mock_scaffold._check_setup_finished_called = False
        result2 = complex_signature(mock_scaffold, 1, 2, 3, 4, c="custom", extra="value")
        assert result2["a"] == 1
        assert result2["b"] == 2
        assert result2["args"] == (3, 4)
        assert result2["c"] == "custom"
        assert result2["kwargs"] == {"extra": "value"}

    def test_decorator_with_functools_wraps(self) -> None:
        """Test that the decorator properly uses functools.wraps."""

        @setupmethod
        @functools.lru_cache(maxsize=2)
        def cached_method(scaffold: MockScaffold, x: int) -> int:
            return x * x

        mock_scaffold = MockScaffold(setup_finished=False)

        # First call
        result1 = cached_method(mock_scaffold, 5)
        assert result1 == 25
        assert mock_scaffold._check_setup_finished_called

        # Reset and call again (should use cache, but still check setup)
        mock_scaffold._check_setup_finished_called = False
        result2 = cached_method(mock_scaffold, 5)
        assert result2 == 25
        assert mock_scaffold._check_setup_finished_called  # Setup check should still be called

    def test_decorator_returns_correct_type(self) -> None:
        """Test that the decorator returns a callable with the correct type."""

        def plain_function(scaffold: MockScaffold) -> str:
            return "result"

        decorated = setupmethod(plain_function)

        assert callable(decorated)
        assert hasattr(decorated, '__name__')
        assert decorated.__name__ == 'plain_function'

        mock_scaffold = MockScaffold(setup_finished=False)
        result = decorated(mock_scaffold)

        assert mock_scaffold._check_setup_finished_called
        assert result == "result"

