import pytest
import json
from flask import Flask, current_app
from flask.json import dumps
import typing as t

class TestDumps:
    """Test cases for the dumps function in flask.json"""

    def test_dumps_basic_types(self):
        """Test dumps with basic JSON serializable types"""
        # Test with string
        assert dumps("hello") == '"hello"'

        # Test with integer
        assert dumps(42) == '42'

        # Test with float
        assert dumps(3.14) == '3.14'

        # Test with boolean
        assert dumps(True) == 'true'
        assert dumps(False) == 'false'

        # Test with None
        assert dumps(None) == 'null'

        # Test with list
        assert dumps([1, 2, 3]) == '[1, 2, 3]'

        # Test with dict
        assert dumps({"key": "value"}) == '{"key": "value"}'

        # Test empty structures
        assert dumps([]) == '[]'
        assert dumps({}) == '{}'

    def test_dumps_with_kwargs(self):
        """Test dumps with additional keyword arguments"""
        # Test with indent
        data = {"a": 1, "b": 2}
        result = dumps(data, indent=2)
        expected = '{\n  "a": 1,\n  "b": 2\n}'
        assert result == expected

        # Test with sort_keys
        data = {"b": 2, "a": 1}
        result = dumps(data, sort_keys=True)
        assert result == '{"a": 1, "b": 2}'

        # Test with separators
        data = {"a": 1, "b": 2}
        result = dumps(data, separators=(",", ":"))
        assert result == '{"a":1,"b":2}'

        # Test with ensure_ascii=False
        data = {"message": "café"}
        result = dumps(data, ensure_ascii=False)
        assert result == '{"message": "café"}'

    def test_dumps_with_custom_app_context(self):
        """Test dumps within Flask application context"""
        app = Flask(__name__)

        # Create a custom JSON encoder
        class CustomEncoder(json.JSONEncoder):
            def default(self, obj):
                if isinstance(obj, set):
                    return list(obj)
                return super().default(obj)

        app.json_encoder = CustomEncoder

        with app.app_context():
            # Test with custom encoder handling set
            data = {1, 2, 3}
            result = dumps(data)
            # The set will be converted to list by our custom encoder
            assert result == '[1, 2, 3]'

            # Test that we're using the app's context
            assert current_app == app

            # Test basic types still work
            assert dumps({"test": "value"}) == '{"test": "value"}'

    def test_dumps_without_app_context(self):
        """Test dumps without Flask application context"""
        # Should use standard json.dumps when no app context
        data = {"key": "value"}
        result = dumps(data)
        assert result == json.dumps(data)

        # Test with kwargs
        result = dumps(data, indent=2)
        expected = json.dumps(data, indent=2)
        assert result == expected

    def test_dumps_custom_app_json_provider(self):
        """Test dumps with app.json provider customization"""
        app = Flask(__name__)

        # Mock custom dumps method on app.json
        custom_called = []
        def custom_dumps(obj, **kwargs):
            custom_called.append((obj, kwargs))
            return "CUSTOM_JSON"

        app.json.dumps = custom_dumps

        with app.app_context():
            result = dumps({"test": "data"}, indent=2)
            assert result == "CUSTOM_JSON"
            assert len(custom_called) == 1
            assert custom_called[0][0] == {"test": "data"}
            assert custom_called[0][1]["indent"] == 2

    def test_dumps_type_error(self):
        """Test dumps raises TypeError for non-serializable objects"""
        class NonSerializable:
            pass

        with pytest.raises(TypeError):
            dumps(NonSerializable())

        # Should still raise TypeError even with kwargs
        with pytest.raises(TypeError):
            dumps(NonSerializable(), indent=2)

    def test_dumps_preserves_input_object(self):
        """Test that dumps does not modify the input object"""
        original = {"a": 1, "b": [2, 3]}
        original_copy = {"a": 1, "b": [2, 3]}

        result = dumps(original)
        assert original == original_copy
        assert result == '{"a": 1, "b": [2, 3]}'

    def test_dumps_nested_structures(self):
        """Test dumps with complex nested structures"""
        data = {
            "users": [
                {"id": 1, "name": "Alice", "active": True},
                {"id": 2, "name": "Bob", "active": False}
            ],
            "metadata": {
                "count": 2,
                "page": 1,
                "total": None
            }
        }

        result = dumps(data, sort_keys=True)
        expected = json.dumps(data, sort_keys=True)
        assert result == expected

    def test_dumps_datetime_with_app_encoder(self):
        """Test dumps with datetime objects using app's JSON encoder"""
        from datetime import datetime, date

        app = Flask(__name__)

        class DateTimeEncoder(json.JSONEncoder):
            def default(self, obj):
                if isinstance(obj, (datetime, date)):
                    return obj.isoformat()
                return super().default(obj)

        app.json_encoder = DateTimeEncoder

        with app.app_context():
            # Test with date
            test_date = date(2023, 12, 25)
            result = dumps(test_date)
            # The custom encoder should return ISO format
            assert result == '"2023-12-25"'

            # Test with datetime
            test_datetime = datetime(2023, 12, 25, 10, 30, 45)
            result = dumps(test_datetime)
            assert result == '"2023-12-25T10:30:45"'

    def test_dumps_empty_app_context(self):
        """Test dumps with empty Flask application context"""
        app = Flask(__name__)

        with app.app_context():
            # Should use app.json.dumps even with empty app
            data = {"test": "data"}
            result = dumps(data)
            expected = json.dumps(data)
            assert result == expected

    def test_dumps_with_default_kwarg(self):
        """Test dumps with default kwarg for custom serialization"""
        class CustomObject:
            def __init__(self, value):
                self.value = value

        def custom_default(obj):
            if isinstance(obj, CustomObject):
                return {"custom_value": obj.value}
            raise TypeError

        obj = CustomObject("test")

        # Test without app context
        result = dumps(obj, default=custom_default)
        assert result == '{"custom_value": "test"}'

        # Test with app context
        app = Flask(__name__)
        with app.app_context():
            result = dumps(obj, default=custom_default)
            assert result == '{"custom_value": "test"}'

    def test_dumps_mixed_contexts(self):
        """Test dumps switching between app context and no context"""
        app = Flask(__name__)

        # First without context
        result1 = dumps({"a": 1})

        # Then with context
        with app.app_context():
            result2 = dumps({"a": 1})

        # Then without context again
        result3 = dumps({"a": 1})

        assert result1 == result2 == result3 == '{"a": 1}'

    def test_dumps_with_app_and_custom_encoder(self):
        """Test dumps with app context and custom encoder"""
        app = Flask(__name__)

        class CustomEncoder(json.JSONEncoder):
            def default(self, obj):
                if isinstance(obj, complex):
                    return {"real": obj.real, "imag": obj.imag}
                return super().default(obj)

        app.json_encoder = CustomEncoder

        with app.app_context():
            # Test with complex number
            c = complex(1, 2)
            result = dumps(c)
            assert result == '{"real": 1.0, "imag": 2.0}'

            # Test that regular JSON still works
            assert dumps([1, 2, 3]) == '[1, 2, 3]'

    def test_dumps_with_cls_kwarg(self):
        """Test dumps with cls kwarg for custom JSON encoder"""
        class CustomEncoder(json.JSONEncoder):
            def default(self, obj):
                if isinstance(obj, range):
                    return list(obj)
                return super().default(obj)

        # Test without app context
        r = range(3)
        result = dumps(r, cls=CustomEncoder)
        assert result == '[0, 1, 2]'

        # Test with app context (should still use provided cls)
        app = Flask(__name__)
        with app.app_context():
            result = dumps(r, cls=CustomEncoder)
            assert result == '[0, 1, 2]'

    def test_dumps_with_app_context_and_default(self):
        """Test dumps with app context and default parameter"""
        app = Flask(__name__)

        class CustomObject:
            def __init__(self, value):
                self.value = value

        def custom_default(obj):
            if isinstance(obj, CustomObject):
                return {"custom": obj.value}
            raise TypeError

        with app.app_context():
            obj = CustomObject("test")
            result = dumps(obj, default=custom_default)
            assert result == '{"custom": "test"}'

    def test_dumps_with_app_context_and_cls(self):
        """Test dumps with app context and cls parameter"""
        app = Flask(__name__)

        class CustomEncoder(json.JSONEncoder):
            def default(self, obj):
                if isinstance(obj, set):
                    return list(obj)
                return super().default(obj)

        with app.app_context():
            data = {1, 2, 3}
            result = dumps(data, cls=CustomEncoder)
            assert result == '[1, 2, 3]'

    def test_dumps_with_app_context_and_both_cls_default(self):
        """Test dumps with app context, cls and default parameters"""
        app = Flask(__name__)

        class CustomEncoder(json.JSONEncoder):
            def default(self, obj):
                if isinstance(obj, set):
                    return list(obj)
                return super().default(obj)

        def custom_default(obj):
            if isinstance(obj, complex):
                return {"real": obj.real, "imag": obj.imag}
            raise TypeError

        with app.app_context():
            # Test with set using cls
            data = {1, 2, 3}
            result = dumps(data, cls=CustomEncoder)
            assert result == '[1, 2, 3]'

            # Test with complex using default
            c = complex(1, 2)
            result = dumps(c, default=custom_default)
            assert result == '{"real": 1.0, "imag": 2.0}'

