    def test_dumps_with_app_context_and_cls(self):
        """Test dumps with app context and cls parameter"""
        app = Flask(__name__)

        class CustomEncoder(json.JSONEncoder):
            def default(self, obj):
                if isinstance(obj, set):
                    return list(obj)
                return super().default(obj)

        with app.app_context():
            data = {1, 2, 3}
            result = dumps(data, cls=CustomEncoder)
            assert result == '[1, 2, 3]'

    def test_dumps_with_app_context_and_both_cls_default(self):
        """Test dumps with app context, cls and default parameters"""
        app = Flask(__name__)

        class CustomEncoder(json.JSONEncoder):
            def default(self, obj):
                if isinstance(obj, set):
                    return list(obj)
                return super().default(obj)

