import pytest
import click
import typing as t
from unittest.mock import Mock, patch, MagicMock
from flask.cli import AppGroup

class TestDecorator:
    """Test cases for AppGroup.decorator method"""

    def test_decorator_basic_function(self):
        """Test that decorator correctly wraps a basic function"""
        # Create AppGroup instance
        app_group = AppGroup("test_group")

        # Mock the decorator method since it doesn't exist on AppGroup
        # Based on the function specification, decorator should be a method
        # that wraps a function as a command
        def sample_func():
            return "test_result"

        # Since AppGroup doesn't have a decorator method, we need to test
        # the actual implementation pattern
        # First, let's check what methods AppGroup actually has
        assert hasattr(app_group, 'command')

        # The decorator method should be accessible via the command decorator
        # In Flask CLI, AppGroup.command is used as a decorator
        @app_group.command()
        def sample_command():
            return "test_result"

        # Verify the command was registered
        assert hasattr(app_group, 'commands')
        assert 'sample_command' in app_group.commands

    def test_decorator_with_args_kwargs(self):
        """Test decorator with additional args and kwargs"""
        app_group = AppGroup("test_group")

        # Test using the command decorator with arguments
        @app_group.command(help="Test help text", short_help="Short help")
        def sample_command():
            return "test"

        # Verify command properties
        cmd = app_group.commands['sample_command']
        assert cmd.help == "Test help text"
        assert cmd.short_help == "Short help"

    def test_decorator_with_context_wrapping(self):
        """Test decorator when wrap_for_ctx should be applied"""
        app_group = AppGroup("test_group")

        # Test with with_appcontext decorator which wraps functions with context
        from flask.cli import with_appcontext

        @app_group.command()
        @with_appcontext
        def context_command():
            return "with_context"

        # Verify command was registered
        assert 'context_command' in app_group.commands

    def test_decorator_command_invocation(self):
        """Test that the created command can be invoked"""
        app_group = AppGroup("test_group")

        results = []

        @app_group.command()
        def sample_command(param1, param2):
            results.append((param1, param2))
            return f"Processed {param1} and {param2}"

        # Get the command and invoke it
        cmd = app_group.commands['sample_command']
        # Commands are invoked through Click's CLI system
        # We can test the callback directly
        callback = cmd.callback
        result = callback("value1", "value2")

        assert results == [("value1", "value2")]
        assert result == "Processed value1 and value2"

    def test_decorator_preserves_function_signature(self):
        """Test that the original function signature is preserved"""
        app_group = AppGroup("test_group")

        @app_group.command()
        def complex_func(arg1: str, arg2: int = 5, *args, **kwargs) -> str:
            """A function with complex signature"""
            return f"{arg1}_{arg2}"

        # Verify the command callback has the same parameters
        import inspect
        cmd = app_group.commands['complex_func']
        original_sig = inspect.signature(complex_func)
        command_sig = inspect.signature(cmd.callback)

        # Compare parameter lists
        original_params = list(original_sig.parameters.keys())
        command_params = list(command_sig.parameters.keys())

        assert original_params == command_params

    def test_decorator_inheritance_chain(self):
        """Test that decorator uses super().command properly"""
        app_group = AppGroup("test_group")

        # Mock the parent class's command method
        with patch.object(app_group.__class__.__bases__[0], 'command') as mock_command:
            @app_group.command()
            def sample_command():
                return "test"

            # Verify parent's command was called
            mock_command.assert_called_once()

    def test_decorator_with_class_method(self):
        """Test decorator with class methods"""
        app_group = AppGroup("test_group")

        class TestClass:
            def method(self, param):
                return f"Method: {param}"

        obj = TestClass()

        # Register the bound method as a command
        @app_group.command(name="method")
        def method_command(param):
            return obj.method(param)

        cmd = app_group.commands['method']
        result = cmd.callback("test_param")
        assert result == "Method: test_param"

    def test_decorator_with_lambda(self):
        """Test decorator with lambda functions"""
        app_group = AppGroup("test_group")

        # Lambda needs to be wrapped in a regular function
        lambda_func = lambda x: x * 2

        @app_group.command(name="lambda_command")
        def lambda_wrapper(x):
            return lambda_func(x)

        cmd = app_group.commands['lambda_command']
        result = cmd.callback(5)
        assert result == 10

    def test_decorator_multiple_registrations(self):
        """Test multiple functions can be decorated in same group"""
        app_group = AppGroup("test_group")

        @app_group.command()
        def func1():
            return "func1"

        @app_group.command()
        def func2():
            return "func2"

        assert 'func1' in app_group.commands
        assert 'func2' in app_group.commands
        assert app_group.commands['func1'] != app_group.commands['func2']

    def test_decorator_with_different_kwargs_combinations(self):
        """Test decorator with various keyword argument combinations"""
        app_group = AppGroup("test_group")

        # Test with different kwargs that Click supports
        @app_group.command(
            help="Help text",
            short_help="Short",
            deprecated=True,
            hidden=True,
            no_args_is_help=True
        )
        def sample_command():
            return "test"

        cmd = app_group.commands['sample_command']
        assert cmd.help == "Help text"
        assert cmd.short_help == "Short"
        assert cmd.deprecated is True
        assert cmd.hidden is True

    def test_decorator_error_handling(self):
        """Test error propagation from super().command"""
        app_group = AppGroup("test_group")

        # Mock parent's command to raise an error
        with patch.object(app_group.__class__.__bases__[0], 'command', 
                         side_effect=TypeError("Invalid arguments")):
            with pytest.raises(TypeError, match="Invalid arguments"):
                @app_group.command(invalid_arg="should_fail")
                def failing_command():
                    return "test"

    def test_decorator_returns_click_command(self):
        """Test that decorator always returns a click.Command instance"""
        app_group = AppGroup("test_group")

        @app_group.command()
        def named_func():
            return "named"

        cmd = app_group.commands['named_func']
        assert isinstance(cmd, click.Command)
        assert hasattr(cmd, 'callback')
        assert callable(cmd.callback)

    def test_decorator_with_different_function_types(self):
        """Test decorator with various function types"""
        app_group = AppGroup("test_group")

        # Test with async function
        async def async_func():
            return "async"

        @app_group.command()
        def async_wrapper():
            import asyncio
            return asyncio.run(async_func())

        # Test with generator function
        def generator_func():
            yield "generator"

        @app_group.command()
        def generator_wrapper():
            return next(generator_func())

        # Test with static method
        class TestClass:
            @staticmethod
            def static_method():
                return "static"

        @app_group.command()
        def static_wrapper():
            return TestClass.static_method()

        assert 'async_wrapper' in app_group.commands
        assert 'generator_wrapper' in app_group.commands
        assert 'static_wrapper' in app_group.commands

    def test_decorator_command_properties(self):
        """Test that the created command has proper Click properties"""
        app_group = AppGroup("test_group")

        @app_group.command(
            help="Custom help text",
            epilog="Command epilog",
            name="custom_name"
        )
        def sample_func():
            """Sample function docstring."""
            return "test"

        cmd = app_group.commands['custom_name']
        assert isinstance(cmd, click.Command)
        assert cmd.help == "Custom help text"
        assert cmd.epilog == "Command epilog"
        # Command name should match the provided name
        assert cmd.name == "custom_name"

    def test_decorator_with_app_group_initialization(self):
        """Test AppGroup initialization and basic decorator usage"""
        # Test different ways to create AppGroup
        app_group1 = AppGroup("group1")
        app_group2 = AppGroup(name="group2")

        @app_group1.command()
        def command1():
            return "cmd1"

        @app_group2.command()
        def command2():
            return "cmd2"

        assert 'command1' in app_group1.commands
        assert 'command2' in app_group2.commands

    def test_decorator_chain_with_other_decorators(self):
        """Test decorator chaining with other decorators"""
        app_group = AppGroup("test_group")

        # Chain with other decorators
        def custom_decorator(func):
            def wrapper(*args, **kwargs):
                return f"decorated_{func(*args, **kwargs)}"
            return wrapper

        @app_group.command()
        @custom_decorator
        def chained_command():
            return "result"

        cmd = app_group.commands['chained_command']
        result = cmd.callback()
        assert result == "decorated_result"

