import unittest
from unittest.mock import MagicMock
from flask.json.tag import TagDict

class TestTagDictToJson(unittest.TestCase):
    def setUp(self):
        self.tag_dict = TagDict()
        self.tag_dict.serializer = MagicMock()
        self.tag_dict.serializer.tag = MagicMock(side_effect=lambda x: f"serialized_{x}")

    def test_to_json_with_valid_input(self):
        value = {'key1': 'value1', 'key2': 'value2'}
        expected_output = {'key1__': 'serialized_value1'}
        result = self.tag_dict.to_json(value)
        self.assertEqual(result, expected_output)

    def test_to_json_with_single_key_value_pair(self):
        value = {'key1': 'value1'}
        expected_output = {'key1__': 'serialized_value1'}
        result = self.tag_dict.to_json(value)
        self.assertEqual(result, expected_output)

    def test_to_json_with_empty_dict_raises_stop_iteration(self):
        value = {}
        with self.assertRaises(StopIteration):
            self.tag_dict.to_json(value)

