import unittest
from flask.sansio.blueprints import Blueprint
from jinja2 import Environment

class TestAppTemplateGlobal(unittest.TestCase):

    def setUp(self):
        self.blueprint = Blueprint(name="test_blueprint", import_name=__name__)

    def test_register_function_as_global_with_name(self):
        def sample_function():
            return "Hello, World!"

        self.blueprint.app_template_global(name="custom_name")(sample_function)
        env = Environment()
        env.globals.update(self.blueprint.jinja_globals)
        self.assertIn("custom_name", env.globals)
        self.assertEqual(env.globals["custom_name"](), "Hello, World!")

    def test_register_function_as_global_without_name(self):
        def sample_function():
            return "Hello, World!"

        self.blueprint.app_template_global()(sample_function)
        env = Environment()
        env.globals.update(self.blueprint.jinja_globals)
        self.assertIn("sample_function", env.globals)
        self.assertEqual(env.globals["sample_function"](), "Hello, World!")

    def test_register_function_as_global_with_invalid_name(self):
        def sample_function():
            return "Hello, World!"

        with self.assertRaises(ValueError):
            self.blueprint.app_template_global(name="invalid.name")(sample_function)

    def test_decorator_usage(self):
        @self.blueprint.app_template_global(name="decorated_function")
        def decorated_function():
            return "Decorated Function"

        env = Environment()
        env.globals.update(self.blueprint.jinja_globals)
        self.assertIn("decorated_function", env.globals)
        self.assertEqual(env.globals["decorated_function"](), "Decorated Function")

    def test_return_function_when_called_directly(self):
        def sample_function():
            return "Direct Call"

        result = self.blueprint.app_template_global(sample_function)
        self.assertEqual(result(), "Direct Call")

if __name__ == '__main__':
    unittest.main()

