class TestDumps(unittest.TestCase):

    def test_dumps_standard_json(self):
        obj = {"key": "value"}
        result = dumps(obj)
        expected = json.dumps(obj)
        self.assertEqual(result, expected)

    def test_dumps_with_kwargs(self):
        obj = {"key": "value"}
        result = dumps(obj, indent=4)
        expected = json.dumps(obj, indent=4)
        self.assertEqual(result, expected)

    @patch('flask.json.current_app', None)
    def test_dumps_no_flask_context(self):
        obj = {"key": "value"}
        result = dumps(obj)
        expected = json.dumps(obj)
        self.assertEqual(result, expected)

    def test_dumps_with_flask_context(self):
        app = Flask(__name__)
        with app.app_context():
            app.json_encoder = MagicMock()
            app.json_encoder().encode = MagicMock(return_value='{"mocked": "json"}')
            with patch('flask.json.current_app', app):
                result = dumps({"key": "value"})
                self.assertEqual(result, '{"mocked": "json"}')

    def test_dumps_non_serializable_object(self):
        class NonSerializable:
            pass

        obj = NonSerializable()
        with self.assertRaises(TypeError):
            dumps(obj)

if __name__ == '__main__':
    unittest.main()

