import unittest
import json
from flask.json.provider import DefaultJSONProvider

class TestDefaultJSONProviderDumps(unittest.TestCase):
    def setUp(self):
        self.provider = DefaultJSONProvider()

    def test_dumps_basic_serialization(self):
        obj = {"key": "value"}
        result = self.provider.dumps(obj)
        expected = json.dumps(obj, ensure_ascii=self.provider.ensure_ascii, sort_keys=self.provider.sort_keys)
        self.assertEqual(result, expected)

    def test_dumps_with_custom_kwargs(self):
        obj = {"key": "value"}
        result = self.provider.dumps(obj, indent=4)
        expected = json.dumps(obj, ensure_ascii=self.provider.ensure_ascii, sort_keys=self.provider.sort_keys, indent=4)
        self.assertEqual(result, expected)

    def test_dumps_non_serializable_object_with_default(self):
        class CustomObject:
            pass

        obj = CustomObject()
        result = self.provider.dumps(obj)
        expected = json.dumps(obj, default=self.provider.default, ensure_ascii=self.provider.ensure_ascii, sort_keys=self.provider.sort_keys)
        self.assertEqual(result, expected)

    def test_dumps_ensure_ascii_false(self):
        obj = {"key": "value", "unicode": "üñîçødê"}
        result = self.provider.dumps(obj, ensure_ascii=False)
        expected = json.dumps(obj, ensure_ascii=False, sort_keys=self.provider.sort_keys)
        self.assertEqual(result, expected)

    def test_dumps_sort_keys_false(self):
        obj = {"b": 1, "a": 2}
        result = self.provider.dumps(obj, sort_keys=False)
        expected = json.dumps(obj, ensure_ascii=self.provider.ensure_ascii, sort_keys=False)
        self.assertEqual(result, expected)

    def test_dumps_with_compact_true(self):
        obj = {"key": "value"}
        self.provider.compact = True
        result = self.provider.dumps(obj)
        expected = json.dumps(obj, ensure_ascii=self.provider.ensure_ascii, sort_keys=self.provider.sort_keys, separators=(',', ':'))
        self.assertEqual(result, expected)

    def test_dumps_with_compact_false(self):
        obj = {"key": "value"}
        self.provider.compact = False
        result = self.provider.dumps(obj)
        expected = json.dumps(obj, ensure_ascii=self.provider.ensure_ascii, sort_keys=self.provider.sort_keys)
        self.assertEqual(result, expected)

    def test_dumps_with_invalid_object_raises_type_error(self):
        obj = object()
        with self.assertRaises(TypeError):
            self.provider.dumps(obj)

if __name__ == '__main__':
    unittest.main()

