import unittest
from unittest.mock import MagicMock, patch
import click
from flask.cli import FlaskGroup

class TestMakeContext(unittest.TestCase):

    def setUp(self):
        self.create_app_mock = MagicMock()
        self.flask_group = FlaskGroup(create_app=self.create_app_mock)

    @patch('flask.cli.ScriptInfo')
    @patch('flask.cli.click.Context')
    def test_make_context_with_valid_args(self, mock_click_context, mock_script_info):
        info_name = 'test_command'
        args = ['--option', 'value']
        parent_context = MagicMock(spec=click.Context)
        extra = {'obj': mock_script_info.return_value}

        context = self.flask_group.make_context(info_name, args, parent_context, **extra)

        mock_click_context.assert_called_once_with(
            self.flask_group, info_name, args, parent=parent_context, **extra
        )
        self.assertEqual(context, mock_click_context.return_value)

    @patch('flask.cli.ScriptInfo')
    @patch('flask.cli.click.Context')
    def test_make_context_without_obj_in_extra(self, mock_click_context, mock_script_info):
        info_name = 'test_command'
        args = ['--option', 'value']
        parent_context = None
        extra = {}

        context = self.flask_group.make_context(info_name, args, parent_context, **extra)

        mock_script_info.assert_called_once_with(create_app=self.create_app_mock)
        extra['obj'] = mock_script_info.return_value
        mock_click_context.assert_called_once_with(
            self.flask_group, info_name, args, parent=parent_context, **extra
        )
        self.assertEqual(context, mock_click_context.return_value)

    @patch('flask.cli.ScriptInfo')
    @patch('flask.cli.click.Context')
    def test_make_context_with_none_info_name(self, mock_click_context, mock_script_info):
        info_name = None
        args = ['--option', 'value']
        parent_context = None
        extra = {'obj': mock_script_info.return_value}

        context = self.flask_group.make_context(info_name, args, parent_context, **extra)

        mock_click_context.assert_called_once_with(
            self.flask_group, info_name, args, parent=parent_context, **extra
        )
        self.assertEqual(context, mock_click_context.return_value)

    @patch('flask.cli.ScriptInfo')
    @patch('flask.cli.click.Context')
    def test_make_context_with_invalid_extra(self, mock_click_context, mock_script_info):
        info_name = 'test_command'
        args = ['--option', 'value']
        parent_context = None
        extra = {'invalid_key': 'invalid_value'}

        with self.assertRaises(ValueError):
            self.flask_group.make_context(info_name, args, parent_context, **extra)

if __name__ == '__main__':
    unittest.main()

