import unittest
import sys
import os
from typing import Any

# Add the flask directory to the path to import the module
sys.path.insert(0, os.path.abspath(os.path.join(os.path.dirname(__file__), '../../../../')))

try:
    from flask.sansio.scaffold import setupmethod, Scaffold
except ImportError:
    # If import fails, create minimal mock for testing
    import typing as t
    from functools import update_wrapper

    class Scaffold:
        def __init__(self):
            self._setup_finished = False

        def _check_setup_finished(self, method_name: str) -> None:
            if self._setup_finished:
                raise RuntimeError(f"The setup method '{method_name}' can no longer be called.")

        def finish_setup(self) -> None:
            self._setup_finished = True

    F = t.TypeVar('F', bound=t.Callable[..., Any])

    def setupmethod(f: F) -> F:
        f_name = f.__name__

        def wrapper_func(self: Scaffold, *args: t.Any, **kwargs: t.Any) -> t.Any:
            self._check_setup_finished(f_name)
            return f(self, *args, **kwargs)

        return t.cast(F, update_wrapper(wrapper_func, f))


class TestSetupMethodDecorator(unittest.TestCase):

    def test_setupmethod_allows_execution_before_finish(self):
        """Test that decorated method can be called before setup is finished"""

        class TestScaffold(Scaffold):
            def __init__(self):
                super().__init__()
                self.call_count = 0

            @setupmethod
            def test_method(self, x: int, y: int = 0) -> int:
                self.call_count += 1
                return x + y

        obj = TestScaffold()

        # Should work before finish_setup is called
        result = obj.test_method(10, 5)
        self.assertEqual(result, 15)
        self.assertEqual(obj.call_count, 1)

        # Should work again
        result = obj.test_method(20, y=10)
        self.assertEqual(result, 30)
        self.assertEqual(obj.call_count, 2)

    def test_setupmethod_blocks_after_finish(self):
        """Test that decorated method raises error after setup is finished"""

        class TestScaffold(Scaffold):
            def __init__(self):
                super().__init__()
                self.call_count = 0

            @setupmethod
            def test_method(self) -> str:
                self.call_count += 1
                return "called"

        obj = TestScaffold()

        # Should work before finishing
        result = obj.test_method()
        self.assertEqual(result, "called")
        self.assertEqual(obj.call_count, 1)

        # Finish setup
        obj.finish_setup()

        # Should raise RuntimeError after finishing
        with self.assertRaises(RuntimeError) as cm:
            obj.test_method()

        self.assertIn("The setup method 'test_method' can no longer be called", str(cm.exception))
        self.assertEqual(obj.call_count, 1)  # Should not have been called again

    def test_setupmethod_preserves_function_metadata(self):
        """Test that decorator preserves function name and docstring"""

        class TestScaffold(Scaffold):
            @setupmethod
            def example_method(self, x: int) -> int:
                """Example method docstring"""
                return x * 2

        obj = TestScaffold()

        # Check function metadata
        self.assertEqual(obj.example_method.__name__, "example_method")
        self.assertEqual(obj.example_method.__doc__, "Example method docstring")

        # Check it still works
        result = obj.example_method(5)
        self.assertEqual(result, 10)

    def test_setupmethod_with_different_signatures(self):
        """Test decorator works with methods of various signatures"""

        class TestScaffold(Scaffold):
            @setupmethod
            def no_args(self) -> str:
                return "no_args"

            @setupmethod
            def with_args(self, a: int, b: str) -> tuple:
                return (a, b)

            @setupmethod
            def with_kwargs(self, x: int = 0, y: str = "default") -> dict:
                return {"x": x, "y": y}

            @setupmethod
            def mixed_args(self, a: int, b: int, *args, c: str = "c", **kwargs) -> tuple:
                return (a, b, args, c, kwargs)

        obj = TestScaffold()

        # Test no_args
        self.assertEqual(obj.no_args(), "no_args")

        # Test with_args
        self.assertEqual(obj.with_args(1, "test"), (1, "test"))

        # Test with_kwargs
        self.assertEqual(obj.with_kwargs(x=10, y="custom"), {"x": 10, "y": "custom"})
        self.assertEqual(obj.with_kwargs(), {"x": 0, "y": "default"})

        # Test mixed_args
        result = obj.mixed_args(1, 2, 3, 4, c="custom", d="extra")
        self.assertEqual(result, (1, 2, (3, 4), "custom", {"d": "extra"}))

    def test_multiple_decorated_methods(self):
        """Test that multiple decorated methods work independently"""

        class TestScaffold(Scaffold):
            def __init__(self):
                super().__init__()
                self.method1_called = 0
                self.method2_called = 0

            @setupmethod
            def method1(self) -> str:
                self.method1_called += 1
                return "method1"

            @setupmethod
            def method2(self, value: int) -> int:
                self.method2_called += 1
                return value * 2

        obj = TestScaffold()

        # Call both methods
        self.assertEqual(obj.method1(), "method1")
        self.assertEqual(obj.method2(5), 10)
        self.assertEqual(obj.method1_called, 1)
        self.assertEqual(obj.method2_called, 1)

        # Finish setup
        obj.finish_setup()

        # Both should now fail
        with self.assertRaises(RuntimeError) as cm:
            obj.method1()
        self.assertIn("method1", str(cm.exception))

        with self.assertRaises(RuntimeError) as cm:
            obj.method2(10)
        self.assertIn("method2", str(cm.exception))

        # Call counts should remain unchanged
        self.assertEqual(obj.method1_called, 1)
        self.assertEqual(obj.method2_called, 1)

    def test_nested_decorator_scenario(self):
        """Test that setupmethod works when combined with other decorators"""

        # Define a simple decorator to test combination
        def double_result(func):
            def wrapper(self, *args, **kwargs):
                result = func(self, *args, **kwargs)
                return result * 2
            return wrapper

        class TestScaffold(Scaffold):
            @setupmethod
            @double_result
            def doubled_method(self, x: int) -> int:
                return x + 1

            @double_result
            @setupmethod
            def another_doubled_method(self, x: int) -> int:
                return x + 2

        obj = TestScaffold()

        # Test first order: setupmethod then double_result
        # (x + 1) * 2
        self.assertEqual(obj.doubled_method(5), 12)  # (5 + 1) * 2 = 12

        # Test second order: double_result then setupmethod  
        # (x + 2) * 2
        self.assertEqual(obj.another_doubled_method(5), 14)  # (5 + 2) * 2 = 14

        # Finish and verify both are blocked
        obj.finish_setup()

        with self.assertRaises(RuntimeError):
            obj.doubled_method(10)

        with self.assertRaises(RuntimeError):
            obj.another_doubled_method(10)

    def test_exception_in_wrapped_method(self):
        """Test that exceptions in the wrapped method propagate correctly"""

        class TestScaffold(Scaffold):
            @setupmethod
            def failing_method(self, should_fail: bool) -> str:
                if should_fail:
                    raise ValueError("Intentional failure")
                return "success"

        obj = TestScaffold()

        # Should work without failure
        self.assertEqual(obj.failing_method(False), "success")

        # Should propagate exception
        with self.assertRaises(ValueError) as cm:
            obj.failing_method(True)
        self.assertEqual(str(cm.exception), "Intentional failure")

        # After finishing setup, should get RuntimeError instead of ValueError
        obj.finish_setup()

        with self.assertRaises(RuntimeError) as cm:
            obj.failing_method(False)
        self.assertIn("failing_method", str(cm.exception))


if __name__ == '__main__':
    unittest.main()

