import unittest
from unittest.mock import MagicMock
from flask.json.tag import TagDict

class TestTagDictCheck(unittest.TestCase):
    def setUp(self):
        self.tag_dict = TagDict()
        self.tag_dict.serializer = MagicMock()
        self.tag_dict.serializer.tags = {'valid_key'}

    def test_check_with_valid_dict(self):
        value = {'valid_key': 'value'}
        result = self.tag_dict.check(value)
        self.assertTrue(result)

    def test_check_with_invalid_dict_key(self):
        value = {'invalid_key': 'value'}
        result = self.tag_dict.check(value)
        self.assertFalse(result)

    def test_check_with_empty_dict(self):
        value = {}
        result = self.tag_dict.check(value)
        self.assertFalse(result)

    def test_check_with_multiple_keys_dict(self):
        value = {'valid_key': 'value', 'another_key': 'value2'}
        result = self.tag_dict.check(value)
        self.assertFalse(result)

    def test_check_with_non_dict(self):
        value = ['valid_key', 'value']
        result = self.tag_dict.check(value)
        self.assertFalse(result)

if __name__ == '__main__':
    unittest.main()

