import pytest
from flask.json.tag import TagDict
from flask.json.provider import DefaultJSONProvider


class TestTagDictToJson:
    @pytest.fixture
    def serializer(self):
        """Fixture to provide a serializer instance."""
        return DefaultJSONProvider()

    @pytest.fixture
    def tag_dict(self, serializer):
        """Fixture to provide the TagDict instance under test."""
        # Key is set by default in the class definition as " di", 
        # but the implementation of to_json constructs a new key ending in '__'.
        # We need to mock the serializer to verify the call.
        return TagDict(key=" di")

    def test_to_json_single_item_dict(self, tag_dict):
        """Test to_json with a standard single-item dictionary."""
        value = {"test_key": 123}
        result = tag_dict.to_json(value)

        assert isinstance(result, dict)
        # The implementation uses iter(value) to get the key, then appends '__'
        assert "test_key__" in result
        assert result["test_key__"] == 123

    def test_to_json_nested_value(self, tag_dict):
        """Test to_json where the value is a complex type requiring serialization."""
        # Assuming serializer.tag handles tuples (default provider usually does)
        value = {"data": (1, 2, 3)}

        # We patch the serializer to return a known value to verify interaction
        tag_dict.serializer.tag = lambda x: "SERIALIZED"

        result = tag_dict.to_json(value)

        assert result == {"data__": "SERIALIZED"}

    def test_to_json_empty_dict(self, tag_dict):
        """Test to_json behavior with an empty dictionary."""
        # iter({}) raises StopIteration immediately, so next(iter(value)) raises StopIteration
        # Depending on strictness, this might raise an error or handle it.
        # The code provided implies value has at least one item to iterate over.
        with pytest.raises(StopIteration):
            tag_dict.to_json({})

    def test_to_json_uses_first_key_only(self, tag_dict):
        """Test that to_json ignores subsequent keys in the dictionary."""
        # iter(value) returns an iterator. next() gets the first one.
        # The code only accesses value[key].
        value = {"first": 1, "second": 2}

        tag_dict.serializer.tag = lambda x: x * 10

        result = tag_dict.to_json(value)

        assert "first__" in result
        assert result["first__"] == 10
        assert "second__" not in result

    def test_to_json_dynamic_key_construction(self, tag_dict):
        """Test that the key is constructed correctly by appending '__'."""
        value = {"foo": "bar"}
        result = tag_dict.to_json(value)

        assert "foo" in result
        # Check specifically for the appended suffix
        assert result.keys() == {"foo__"}

