import pytest
from flask.sansio.scaffold import Scaffold, setupmethod


class MockScaffold(Scaffold):
    """Concrete implementation of Scaffold for testing purposes."""
    def __init__(self):
        super().__init__()
        self._setup_finished = False

    def _check_setup_finished(self, name: str | None) -> None:
        """Mock implementation to simulate setup check."""
        if self._setup_finished:
            raise RuntimeError(f"Setup finished, cannot call {name}")

    # A sample method to be decorated
    @setupmethod
    def add_rule(self, rule):
        return f"Rule: {rule}"


class TestSetupmethod:
    def test_setupmethod_wrapper_call(self):
        """Test that the decorated method calls the original function."""
        mock = MockScaffold()
        result = mock.add_rule("/home")
        assert result == "Rule: /home"

    def test_setupmethod_raises_on_finished_setup(self):
        """Test that the wrapper raises RuntimeError if setup is finished."""
        mock = MockScaffold()
        mock._setup_finished = True

        with pytest.raises(RuntimeError, match="Setup finished, cannot call add_rule"):
            mock.add_rule("/home")

    def test_setupmethod_preserves_name_and_docstring(self):
        """Test that functools.update_wrapper preserves function metadata."""
        decorated_func = MockScaffold.add_rule
        assert decorated_func.__name__ == "add_rule"
        # Assuming add_rule has no docstring, checking it doesn't error is sufficient,
        # but if we add one it would be preserved. 
        # The main requirement is that it doesn't break the attribute access.
        assert hasattr(decorated_func, "__name__")

    def test_setupmethod_with_args_and_kwargs(self):
        """Test that the wrapper correctly passes *args and **kwargs."""
        mock = MockScaffold()

        # Define a method that takes multiple arguments to ensure forwarding works
        @setupmethod
        def complex_method(self, a, b, c=None):
            return (a, b, c)

        mock.complex_method = complex_method.__get__(mock, type(mock))

        result = mock.complex_method(1, 2, c=3)
        assert result == (1, 2, 3)

