import pytest
from flask import Flask, current_app, Response
from flask.views import View, MethodView
from werkzeug.test import Client
from werkzeug.serving import WSGIRequestHandler
from typing import Any

# Helper View class for testing
class SimpleView(View):
    methods = ["GET"]

    def dispatch_request(self):
        return "Hello World"

class AsyncView(View):
    methods = ["GET"]

    async def dispatch_request(self):
        return "Async Hello"

class ViewWithArgs(View):
    methods = ["GET"]

    def __init__(self, custom_arg):
        self.custom_arg = custom_arg

    def dispatch_request(self):
        return self.custom_arg

class TestViewFunction:

    def test_view_basic_dispatch(self):
        app = Flask(__name__)

        class TestView(View):
            methods = ['GET']

            def dispatch_request(self):
                return 'dispatched'

        app.add_url_rule('/', view_func=TestView.as_view('test'))

        with app.test_client() as client:
            rv = client.get('/')
            assert rv.data == b'dispatched'

    def test_view_with_kwargs(self):
        app = Flask(__name__)

        class TestView(View):
            methods = ['GET']

            def dispatch_request(self, name):
                return f'Hello {name}'

        app.add_url_rule('/<name>', view_func=TestView.as_view('test'))

        with app.test_client() as client:
            rv = client.get('/Flask')
            assert rv.data == b'Hello Flask'

    def test_view_instantiation(self):
        app = Flask(__name__)

        class TestView(View):
            methods = ['GET']

            def __init__(self, value):
                self.value = value

            def dispatch_request(self):
                return str(self.value)

        # Pass init arguments via as_view
        view_func = TestView.as_view('test', value='initialized')
        app.add_url_rule('/', view_func=view_func)

        with app.test_client() as client:
            rv = client.get('/')
            assert rv.data == b'initialized'

    def test_view_automatic_options(self):
        app = Flask(__name__)

        class TestView(View):
            methods = ['GET', 'POST']

            def dispatch_request(self):
                return 'ok'

        app.add_url_rule('/', view_func=TestView.as_view('test'))

        with app.test_client() as client:
            # Flask handles OPTIONS automatically for View classes
            rv = client.open('/', method='OPTIONS')
            assert rv.status_code == 200
            assert b'GET' in rv.headers['Allow']
            assert b'POST' in rv.headers['Allow']

    def test_view_decorator_application(self):
        app = Flask(__name__)

        def custom_decorator(f):
            def wrapper(*args, **kwargs):
                return 'Decorated: ' + f(*args, **kwargs)
            return wrapper

        class TestView(View):
            methods = ['GET']
            decorators = [custom_decorator]

            def dispatch_request(self):
                return 'content'

        app.add_url_rule('/', view_func=TestView.as_view('test'))

        with app.test_client() as client:
            rv = client.get('/')
            assert rv.data == b'Decorated: content'

    def test_view_method_not_allowed(self):
        app = Flask(__name__)

        class TestView(View):
            methods = ['POST']

            def dispatch_request(self):
                return 'posted'

        app.add_url_rule('/', view_func=TestView.as_view('test'))

        with app.test_client() as client:
            rv = client.get('/')
            assert rv.status_code == 405

    def test_view_init_every_request_true(self):
        app = Flask(__name__)

        class TestView(View):
            init_every_request = True
            methods = ['GET']

            def __init__(self):
                self.counter = 0

            def dispatch_request(self):
                self.counter += 1
                return str(self.counter)

        app.add_url_rule('/', view_func=TestView.as_view('test'))

        with app.test_client() as client:
            rv1 = client.get('/')
            assert rv1.data == b'1'
            rv2 = client.get('/')
            assert rv2.data == b'1' # Should be re-initialized

    def test_view_init_every_request_false(self):
        app = Flask(__name__)

        class TestView(View):
            init_every_request = False
            methods = ['GET']

            def __init__(self):
                self.counter = 0

            def dispatch_request(self):
                self.counter += 1
                return str(self.counter)

        app.add_url_rule('/', view_func=TestView.as_view('test'))

        with app.test_client() as client:
            rv1 = client.get('/')
            assert rv1.data == b'1'
            rv2 = client.get('/')
            assert rv2.data == b'2' # Should persist across requests in same context (usually)

    def test_view_class_attribute_access(self):
        # Testing the specific 'view' function logic which accesses view.view_class
        app = Flask(__name__)

        class MyView(View):
            methods = ['GET']
            def dispatch_request(self):
                return "view"

        view_func = MyView.as_view('my_view')

        # The view function returned by as_view has a view_class attribute
        assert hasattr(view_func, 'view_class')
        assert view_func.view_class is MyView

        app.add_url_rule('/', view_func=view_func)
        with app.test_request_context():
            # Simulating the internal call: self = view.view_class()
            # The function under test is essentially the __call__ of the closure
            res = view_func()
            assert res == "view"

