import datetime
import json
import uuid

import pytest
from flask.json.provider import DefaultJSONProvider


class TestDefaultJSONProviderDumps:
    @pytest.fixture
    def provider(self):
        return DefaultJSONProvider()

    def test_dumps_basic_dict(self, provider):
        data = {"key": "value", "number": 123}
        result = provider.dumps(data)
        assert result == '{"key": "value", "number": 123}'

    def test_dumps_basic_list(self, provider):
        data = ["item1", 2, 3.14]
        result = provider.dumps(data)
        assert result == '["item1", 2, 3.14]'

    def test_dumps_nested_structure(self, provider):
        data = {"list": [1, 2, 3], "dict": {"nested": "value"}}
        result = provider.dumps(data)
        assert result == '{"dict": {"nested": "value"}, "list": [1, 2, 3]}'

    def test_dumps_default_sort_keys(self, provider):
        # DefaultJSONProvider sets sort_keys=True by default
        data = {"z": 1, "a": 2, "m": 3}
        result = provider.dumps(data)
        # Keys should be sorted alphabetically: a, m, z
        assert result == '{"a": 2, "m": 3, "z": 1}'

    def test_dumps_override_sort_keys(self, provider):
        # Ensure passing sort_keys=False overrides the default
        data = {"z": 1, "a": 2, "m": 3}
        result = provider.dumps(data, sort_keys=False)
        # Order depends on insertion order (Python 3.7+)
        assert result == '{"z": 1, "a": 2, "m": 3}'

    def test_dumps_default_ensure_ascii(self, provider):
        # DefaultJSONProvider sets ensure_ascii=True by default
        data = {"msg": "こんにちは"}
        result = provider.dumps(data)
        # Should be escaped
        assert result == '{"msg": "\\u3053\\u3093\\u306b\\u3061\\u306f"}'

    def test_dumps_override_ensure_ascii(self, provider):
        # Ensure passing ensure_ascii=False overrides the default
        data = {"msg": "こんにちは"}
        result = provider.dumps(data, ensure_ascii=False)
        assert result == '{"msg": "こんにちは"}'

    def test_dumps_custom_object_handling(self, provider):
        # The default provider uses _default which handles datetime and UUID
        dt = datetime.datetime(2021, 1, 1, 12, 0, 0)
        data = {"time": dt}
        result = provider.dumps(data)
        # Default datetime serialization in Flask is ISO format
        assert result == '{"time": "2021-01-01T12:00:00"}'

    def test_dumps_uuid_handling(self, provider):
        uid = uuid.uuid4()
        data = {"id": uid}
        result = provider.dumps(data)
        # UUID is serialized as a string
        assert result == f'{{"id": "{uid}"}}'

    def test_dumps_indent(self, provider):
        data = {"a": 1, "b": 2}
        result = provider.dumps(data, indent=4)
        expected = '{\n    "a": 1,\n    "b": 2\n}'
        assert result == expected

    def test_dumps_passes_other_kwargs(self, provider):
        # Testing that arbitrary kwargs are passed to json.dumps
        data = {"a": 1, "b": 2}
        # separators is a valid json.dumps arg
        result = provider.dumps(data, separators=(",", ":"))
        # Default with indent=None usually has a space after comma, 
        # compact removes it.
        assert result == '{"a":1,"b":2}'

    def test_dumps_empty_string(self, provider):
        result = provider.dumps("")
        assert result == '""'

    def test_dumps_none(self, provider):
        result = provider.dumps(None)
        assert result == "null"

