import pytest
import click
from flask import Flask
from flask.cli import AppGroup, with_appcontext


class TestDecorator:
    """Test cases for the decorator method in AppGroup."""

    def test_decorator_basic_command(self):
        """Test that the decorator creates a basic Click command."""
        app = Flask(__name__)
        app_group = AppGroup("test-group")

        @app_group.decorator()
        def basic_cmd():
            click.echo("Basic output")

        @app.cli.command("run")
        def run():
            ctx = click.Context(app_group)
            ctx.invoke(basic_cmd)

        runner = app.test_cli_runner()
        result = runner.invoke(["run"])
        assert result.exit_code == 0
        assert "Basic output" in result.output

    def test_decorator_with_arguments(self):
        """Test that the decorator passes arguments through to the command."""
        app = Flask(__name__)
        app_group = AppGroup("test-group")

        @app_group.decorator()
        @click.argument("arg_name")
        def cmd_with_args(arg_name):
            click.echo(f"Arg: {arg_name}")

        @app.cli.command("run")
        def run():
            ctx = click.Context(app_group)
            ctx.invoke(cmd_with_args, arg_name="value")

        runner = app.test_cli_runner()
        result = runner.invoke(["run"])
        assert result.exit_code == 0
        assert "Arg: value" in result.output

    def test_decorator_with_appcontext(self):
        """Test that the decorator wraps the function with app context when wrap_for_ctx is True."""
        app = Flask(__name__)
        app_group = AppGroup("test-group", wrap_for_ctx=True)

        @app_group.decorator()
        def ctx_cmd():
            from flask import current_app
            click.echo(current_app.name)

        @app.cli.command("run")
        def run():
            ctx = click.Context(app_group)
            ctx.invoke(ctx_cmd)

        runner = app.test_cli_runner()
        result = runner.invoke(["run"])
        assert result.exit_code == 0
        assert "test" in result.output

    def test_decorator_command_options(self):
        """Test that standard Click options can be applied."""
        app = Flask(__name__)
        app_group = AppGroup("test-group")

        @app_group.decorator()
        @click.option("--count", default=1, help="Number of greetings.")
        def option_cmd(count):
            for _ in range(count):
                click.echo("Hello")

        @app.cli.command("run")
        def run():
            ctx = click.Context(app_group)
            ctx.invoke(option_cmd, count=2)

        runner = app.test_cli_runner()
        result = runner.invoke(["run"])
        assert result.exit_code == 0
        assert result.output == "Hello\nHello\n"

    def test_decorator_pass_obj(self):
        """Test that the command passes the Click context if configured."""
        app = Flask(__name__)
        app_group = AppGroup("test-group")

        @app_group.decorator()
        @click.pass_context
        def pass_obj_cmd(ctx):
            click.echo(f"Context: {ctx.info_name}")

        @app.cli.command("run")
        def run():
            ctx = click.Context(app_group)
            ctx.invoke(pass_obj_cmd)

        runner = app.test_cli_runner()
        result = runner.invoke(["run"])
        assert result.exit_code == 0
        assert "pass-obj-cmd" in result.output

