import pytest
import click
from flask import Flask, current_app
from flask.cli import ScriptInfo


@click.command()
def dummy_command():
    return "dummy_output"


class TestDecorator:

    def test_decorator_with_current_app(self, app):
        """Test that the decorator function works when current_app is present."""
        f = dummy_command

        def wrapper(ctx, *args, **kwargs):
            if not current_app:
                app_obj = ctx.ensure_object(ScriptInfo).load_app()
                ctx.with_resource(app_obj.app_context())
            return ctx.invoke(f, *args, **kwargs)

        with app.app_context():
            ctx = click.Context(dummy_command)
            result = wrapper(ctx)
            assert result == "dummy_output"

    def test_decorator_without_current_app(self):
        """Test that the decorator function loads the app when current_app is not present."""
        app = Flask(__name__)

        script_info = ScriptInfo(create_app=lambda: app)
        ctx = click.Context(dummy_command)
        ctx.obj = script_info

        f = dummy_command

        def wrapper(ctx, *args, **kwargs):
            if not current_app:
                loaded_app = ctx.ensure_object(ScriptInfo).load_app()
                ctx.with_resource(loaded_app.app_context())
            return ctx.invoke(f, *args, **kwargs)

        result = wrapper(ctx)
        assert result == "dummy_output"

    def test_decorator_invokes_with_args_and_kwargs(self):
        """Test that the decorator passes through arguments and keyword arguments correctly."""
        app = Flask(__name__)

        @click.command()
        @click.argument("name")
        @click.option("--count", default=1)
        def complex_cmd(name, count):
            return f"{name}-{count}"

        f = complex_cmd

        with app.app_context():
            def wrapper(ctx, *args, **kwargs):
                if not current_app:
                    app_obj = ctx.ensure_object(ScriptInfo).load_app()
                    ctx.with_resource(app_obj.app_context())
                return ctx.invoke(f, *args, **kwargs)

            ctx = click.Context(complex_cmd)
            result = wrapper(ctx, "test", count=5)
            assert result == "test-5"

    def test_decorator_without_current_app_and_no_script_info(self):
        """Test behavior when current_app is missing and ScriptInfo cannot load app."""
        ctx = click.Context(dummy_command)

        f = dummy_command

        def wrapper(ctx, *args, **kwargs):
            if not current_app:
                loaded_app = ctx.ensure_object(ScriptInfo).load_app()
                ctx.with_resource(loaded_app.app_context())
            return ctx.invoke(f, *args, **kwargs)

        with pytest.raises(RuntimeError):
            wrapper(ctx)

