import pytest
from flask.sansio.app import App

class TestSelectJinjaAutoescape:

    @pytest.fixture
    def app(self):
        return App(import_name="test_app")

    def test_select_jinja_autoescape_with_none_filename(self, app):
        result = app.select_jinja_autoescape(None)
        assert result is True

    def test_select_jinja_autoescape_with_html_extension(self, app):
        result = app.select_jinja_autoescape("template.html")
        assert result is True

    def test_select_jinja_autoescape_with_htm_extension(self, app):
        result = app.select_jinja_autoescape("template.htm")
        assert result is True

    def test_select_jinja_autoescape_with_xml_extension(self, app):
        result = app.select_jinja_autoescape("template.xml")
        assert result is True

    def test_select_jinja_autoescape_with_xhtml_extension(self, app):
        result = app.select_jinja_autoescape("template.xhtml")
        assert result is True

    def test_select_jinja_autoescape_with_svg_extension(self, app):
        result = app.select_jinja_autoescape("image.svg")
        assert result is True

    def test_select_jinja_autoescape_with_non_template_extension(self, app):
        result = app.select_jinja_autoescape("style.css")
        assert result is False

    def test_select_jinja_autoescape_with_no_extension(self, app):
        result = app.select_jinja_autoescape("README")
        assert result is False

    def test_select_jinja_autoescape_with_empty_string(self, app):
        result = app.select_jinja_autoescape("")
        assert result is False

    def test_select_jinja_autoescape_with_multiple_dots(self, app):
        result = app.select_jinja_autoescape("file.test.html")
        assert result is True

