        assert app.jinja_env.filters['test_filter'] == test_filter

    def test_add_template_filter_overwrites_existing(self):
        app = App(__name__)
        def original_filter(value):
            return value.upper()

        def new_filter(value):
            return value.lower()

        app.add_template_filter(original_filter, 'test_filter')
        app.add_template_filter(new_filter, 'test_filter')
        assert app.jinja_env.filters['test_filter'] == new_filter

