    def test_converts_timedelta_to_seconds(self, mock_current_app, blueprint):
        mock_current_app.config = {"SEND_FILE_MAX_AGE_DEFAULT": timedelta(hours=1)}
        result = blueprint.get_send_file_max_age("test_file.txt")
        assert result == 3600

    @patch('flask.blueprints.current_app')
    def test_handles_filename_none(self, mock_current_app, blueprint):
