import unittest
from unittest.mock import Mock
import sys
import os

sys.path.insert(0, os.path.abspath(os.path.join(os.path.dirname(__file__), '../../../../')))

from flask.json.tag import TagDict

class TestTagDictCheck(unittest.TestCase):
    def setUp(self):
        """Set up test fixtures before each test method."""
        self.serializer = Mock()
        self.tag_dict = TagDict(self.serializer)

    def test_valid_dict_with_matching_tag(self):
        """Test with valid dictionary containing one key that exists in serializer's tags."""
        self.serializer.tags = ["tag1", "tag2", "tag3"]
        value = {"tag1": "some_value"}
        result = self.tag_dict.check(value)
        self.assertTrue(result)

    def test_valid_dict_with_non_matching_tag(self):
        """Test with valid dictionary containing one key that does NOT exist in serializer's tags."""
        self.serializer.tags = ["tag1", "tag2", "tag3"]
        value = {"tag4": "some_value"}
        result = self.tag_dict.check(value)
        self.assertFalse(result)

    def test_empty_dict(self):
        """Test with empty dictionary."""
        self.serializer.tags = ["tag1", "tag2", "tag3"]
        value = {}
        result = self.tag_dict.check(value)
        self.assertFalse(result)

    def test_dict_with_multiple_keys(self):
        """Test with dictionary containing multiple keys."""
        self.serializer.tags = ["tag1", "tag2", "tag3"]
        value = {"tag1": "val1", "tag2": "val2"}
        result = self.tag_dict.check(value)
        self.assertFalse(result)

    def test_none_value(self):
        """Test with None value."""
        self.serializer.tags = ["tag1", "tag2", "tag3"]
        value = None
        result = self.tag_dict.check(value)
        self.assertFalse(result)

    def test_string_value(self):
        """Test with string value (not a dictionary)."""
        self.serializer.tags = ["tag1", "tag2", "tag3"]
        value = "not a dict"
        result = self.tag_dict.check(value)
        self.assertFalse(result)

    def test_list_value(self):
        """Test with list value (not a dictionary)."""
        self.serializer.tags = ["tag1", "tag2", "tag3"]
        value = ["item1", "item2"]
        result = self.tag_dict.check(value)
        self.assertFalse(result)

    def test_empty_tags_in_serializer(self):
        """Test when serializer's tags attribute is empty."""
        self.serializer.tags = []
        value = {"any_tag": "value"}
        result = self.tag_dict.check(value)
        self.assertFalse(result)

    def test_tags_attribute_missing_in_serializer(self):
        """Test when serializer doesn't have tags attribute (should raise AttributeError)."""
        del self.serializer.tags
        value = {"tag1": "value"}
        result = self.tag_dict.check(value)
        self.assertFalse(result)

    def test_dict_with_numeric_key(self):
        """Test with dictionary containing numeric key."""
        self.serializer.tags = ["tag1", "tag2", "tag3"]
        value = {123: "value"}
        result = self.tag_dict.check(value)
        self.assertFalse(result)

    def test_dict_with_none_key(self):
        """Test with dictionary containing None as key."""
        self.serializer.tags = ["tag1", "tag2", "tag3"]
        value = {None: "value"}
        result = self.tag_dict.check(value)
        self.assertFalse(result)

    def test_case_sensitive_tags(self):
        """Test case sensitivity in tag matching."""
        self.serializer.tags = ["Tag1", "Tag2", "Tag3"]
        value = {"tag1": "value"}
        result = self.tag_dict.check(value)
        self.assertFalse(result)

    def test_dict_with_duplicate_tags_in_serializer(self):
        """Test when serializer's tags contain duplicates."""
        self.serializer.tags = ["tag1", "tag1", "tag2"]
        value = {"tag1": "value"}
        result = self.tag_dict.check(value)
        self.assertTrue(result)

    def test_dict_with_empty_string_tag(self):
        """Test with dictionary containing empty string as key."""
        self.serializer.tags = ["", "tag1", "tag2"]
        value = {"": "value"}
        result = self.tag_dict.check(value)
        self.assertTrue(result)

    def test_value_with_nested_dict(self):
        """Test with nested dictionary (still only one key at top level)."""
        self.serializer.tags = ["tag1", "tag2", "tag3"]
        value = {"tag1": {"nested": "dict"}}
        result = self.tag_dict.check(value)
        self.assertTrue(result)

    def test_tags_as_set(self):
        """Test when serializer's tags is a set instead of list."""
        self.serializer.tags = {"tag1", "tag2", "tag3"}
        value = {"tag1": "value"}
        result = self.tag_dict.check(value)
        self.assertTrue(result)

    def test_tags_as_tuple(self):
        """Test when serializer's tags is a tuple."""
        self.serializer.tags = ("tag1", "tag2", "tag3")
        value = {"tag1": "value"}
        result = self.tag_dict.check(value)
        self.assertTrue(result)

    def test_dict_with_special_characters_in_key(self):
        """Test with dictionary key containing special characters."""
        self.serializer.tags = ["tag-1", "tag_2", "tag@3"]
        value = {"tag-1": "value"}
        result = self.tag_dict.check(value)
        self.assertTrue(result)

    def test_serializer_tags_being_modified_during_check(self):
        """Test that modifying tags during check doesn't affect the method."""
        original_tags = ["tag1", "tag2"]
        self.serializer.tags = original_tags.copy()
        value = {"tag1": "value"}

        # Simulate changing tags during check
        def side_effect():
            self.serializer.tags = ["different_tag"]
            return original_tags

        result = self.tag_dict.check(value)
        self.assertTrue(result)

if __name__ == '__main__':
    unittest.main()

