import unittest
import typing as t
from unittest import mock
import flask
from flask import views
from flask.typing import ResponseReturnValue as ft_ResponseReturnValue


class TestViewMethod(unittest.TestCase):
    def setUp(self):
        self.app = flask.Flask(__name__)
        self.app_context = self.app.app_context()
        self.app_context.push()

        class TestViewClass(views.View):
            methods = ['GET', 'POST']
            init_every_request = True
            decorators = []

            def dispatch_request(self, **kwargs):
                return f"Test Response with kwargs: {kwargs}"

        self.TestViewClass = TestViewClass
        self.view_func = views.View.view

    def tearDown(self):
        self.app_context.pop()

    def test_view_basic_functionality(self):
        """Test basic view functionality with minimal kwargs"""
        result = self.view_func(view_class=self.TestViewClass, arg1="value1")
        self.assertEqual(result, "Test Response with kwargs: {'arg1': 'value1'}")

    def test_view_with_multiple_kwargs(self):
        """Test view with multiple keyword arguments"""
        result = self.view_func(
            view_class=self.TestViewClass,
            user_id=123,
            action="update",
            data={"name": "test"}
        )
        expected = "Test Response with kwargs: {'user_id': 123, 'action': 'update', 'data': {'name': 'test'}}"
        self.assertEqual(result, expected)

    def test_view_with_empty_kwargs(self):
        """Test view with no keyword arguments"""
        result = self.view_func(view_class=self.TestViewClass)
        self.assertEqual(result, "Test Response with kwargs: {}")

    def test_view_with_none_values(self):
        """Test view with None values in kwargs"""
        result = self.view_func(
            view_class=self.TestViewClass,
            param1=None,
            param2="not_none"
        )
        expected = "Test Response with kwargs: {'param1': None, 'param2': 'not_none'}"
        self.assertEqual(result, expected)

    def test_view_different_response_types(self):
        """Test view returning different response types"""
        class CustomResponseView(views.View):
            def dispatch_request(self, **kwargs):
                if kwargs.get('type') == 'json':
                    return {'status': 'success', 'data': kwargs}
                elif kwargs.get('type') == 'tuple':
                    return ('Custom Message', 201)
                return "Default Response"

        # Test JSON response
        result = self.view_func(view_class=CustomResponseView, type='json', id=5)
        self.assertEqual(result, {'status': 'success', 'data': {'type': 'json', 'id': 5}})

        # Test tuple response
        result = self.view_func(view_class=CustomResponseView, type='tuple')
        self.assertEqual(result, ('Custom Message', 201))

        # Test default response
        result = self.view_func(view_class=CustomResponseView)
        self.assertEqual(result, "Default Response")

    def test_view_with_custom_view_class_properties(self):
        """Test view with custom class properties"""
        class CustomView(views.View):
            methods = ['PUT', 'DELETE']
            provide_automatic_options = False
            decorators = [lambda f: f]
            init_every_request = False

            def dispatch_request(self, **kwargs):
                return f"Custom properties: {kwargs}"

        result = self.view_func(view_class=CustomView, test="property")
        self.assertEqual(result, "Custom properties: {'test': 'property'}")

        # Verify class properties
        self.assertEqual(CustomView.methods, ['PUT', 'DELETE'])
        self.assertEqual(CustomView.provide_automatic_options, False)
        self.assertEqual(CustomView.init_every_request, False)

    def test_view_attribute_error_missing_view_class(self):
        """Test AttributeError when view_class is not provided"""
        with self.assertRaises(AttributeError):
            self.view_func(test="value")

    def test_view_attribute_error_missing_dispatch_request(self):
        """Test AttributeError when view_class doesn't have dispatch_request"""
        class InvalidView(views.View):
            pass

        with self.assertRaises(AttributeError):
            self.view_func(view_class=InvalidView)

    def test_view_type_error_invalid_dispatch_request(self):
        """Test TypeError when dispatch_request receives incompatible arguments"""
        class StrictView(views.View):
            def dispatch_request(self, required_arg: str):
                return f"Got: {required_arg}"

        # Missing required argument should raise TypeError
        with self.assertRaises(TypeError):
            self.view_func(view_class=StrictView)

    def test_view_runtime_error_no_app_context(self):
        """Test RuntimeError when there's no application context"""
        self.app_context.pop()

        with self.assertRaises(RuntimeError):
            self.view_func(view_class=self.TestViewClass)

    def test_view_ensure_sync_usage(self):
        """Test that ensure_sync is properly used"""
        with mock.patch('flask.views.ensure_sync') as mock_ensure_sync:
            mock_ensure_sync.return_value = lambda **kwargs: "Mocked Response"

            result = self.view_func(view_class=self.TestViewClass, test="sync")

            # Verify ensure_sync was called
            self.assertTrue(mock_ensure_sync.called)
            # Verify our mocked result
            self.assertEqual(result, "Mocked Response")

    def test_view_instance_creation(self):
        """Test that a new view instance is created each time"""
        instance_count = 0

        class CountingView(views.View):
            def __init__(self):
                nonlocal instance_count
                instance_count += 1
                super().__init__()

            def dispatch_request(self, **kwargs):
                return f"Instance #{instance_count}"

        # First call
        result1 = self.view_func(view_class=CountingView)
        self.assertEqual(result1, "Instance #1")

        # Second call should create new instance
        result2 = self.view_func(view_class=CountingView)
        self.assertEqual(result2, "Instance #2")

    def test_view_with_methods_property(self):
        """Test view with custom methods property"""
        class MethodsView(views.View):
            methods = ['GET', 'POST', 'PATCH']

            def dispatch_request(self, **kwargs):
                return f"Methods: {self.methods}, kwargs: {kwargs}"

        result = self.view_func(view_class=MethodsView, action="test")
        self.assertEqual(result, "Methods: ['GET', 'POST', 'PATCH'], kwargs: {'action': 'test'}")

    def test_view_with_decorators(self):
        """Test view with decorators property"""
        call_log = []

        def decorator1(func):
            def wrapper(*args, **kwargs):
                call_log.append('decorator1')
                return func(*args, **kwargs)
            return wrapper

        def decorator2(func):
            def wrapper(*args, **kwargs):
                call_log.append('decorator2')
                return func(*args, **kwargs)
            return wrapper

        class DecoratedView(views.View):
            decorators = [decorator1, decorator2]

            def dispatch_request(self, **kwargs):
                call_log.append('dispatch_request')
                return f"Decorated: {kwargs}"

        result = self.view_func(view_class=DecoratedView, test="decorated")

        self.assertEqual(result, "Decorated: {'test': 'decorated'}")
        self.assertEqual(call_log, ['decorator1', 'decorator2', 'dispatch_request'])

    def test_view_init_every_request_true(self):
        """Test behavior when init_every_request is True (default)"""
        class InitTrackingView(views.View):
            init_every_request = True
            init_count = 0

            def __init__(self):
                super().__init__()
                InitTrackingView.init_count += 1

            def dispatch_request(self, **kwargs):
                return f"Init count: {self.init_count}"

        # First call
        result1 = self.view_func(view_class=InitTrackingView)
        self.assertEqual(result1, "Init count: 1")

        # Reset counter for second call
        InitTrackingView.init_count = 0
        result2 = self.view_func(view_class=InitTrackingView)
        self.assertEqual(result2, "Init count: 1")

    def test_view_init_every_request_false(self):
        """Test behavior when init_every_request is False"""
        class SharedInitView(views.View):
            init_every_request = False
            shared_state = {"count": 0}

            def dispatch_request(self, **kwargs):
                self.shared_state["count"] += 1
                return f"Shared count: {self.shared_state['count']}"

        # Multiple calls should share state
        result1 = self.view_func(view_class=SharedInitView)
        self.assertEqual(result1, "Shared count: 1")

        result2 = self.view_func(view_class=SharedInitView)
        self.assertEqual(result2, "Shared count: 2")

    def test_view_with_exception_in_dispatch(self):
        """Test view when dispatch_request raises an exception"""
        class ExceptionView(views.View):
            def dispatch_request(self, **kwargs):
                raise ValueError("Test exception from dispatch")

        with self.assertRaises(ValueError) as context:
            self.view_func(view_class=ExceptionView)

        self.assertEqual(str(context.exception), "Test exception from dispatch")

    def test_view_with_complex_nested_kwargs(self):
        """Test view with complex nested data structures in kwargs"""
        complex_data = {
            "users": [
                {"id": 1, "name": "Alice", "roles": ["admin", "user"]},
                {"id": 2, "name": "Bob", "roles": ["user"]}
            ],
            "metadata": {
                "total": 2,
                "page": 1,
                "filters": {"active": True, "verified": False}
            }
        }

        result = self.view_func(
            view_class=self.TestViewClass,
            data=complex_data,
            format="json"
        )

        expected = f"Test Response with kwargs: {{'data': {complex_data}, 'format': 'json'}}"
        self.assertEqual(result, expected)

    def test_view_return_type_compatibility(self):
        """Test that the return type is compatible with ResponseReturnValue"""
        class VariousReturnsView(views.View):
            def dispatch_request(self, return_type, **kwargs):
                if return_type == 'string':
                    return "String response"
                elif return_type == 'dict':
                    return {"key": "value", "status": 200}
                elif return_type == 'tuple':
                    return ({"data": "test"}, 201, {'Header': 'Value'})
                elif return_type == 'list':
                    return ["item1", "item2"]
                elif return_type == 'none':
                    return None
                else:
                    return "default"

        # Test various return types that should be compatible
        test_cases = [
            ('string', "String response"),
            ('dict', {"key": "value", "status": 200}),
            ('tuple', ({"data": "test"}, 201, {'Header': 'Value'})),
            ('list', ["item1", "item2"]),
            ('none', None),
        ]

        for return_type, expected in test_cases:
            with self.subTest(return_type=return_type):
                result = self.view_func(
                    view_class=VariousReturnsView,
                    return_type=return_type
                )
                self.assertEqual(result, expected)


if __name__ == '__main__':
    unittest.main()

