        if not self.has_blueprint:
            self.skipTest("Blueprint class not available")

    def _get_decorator(self, bp):
        dec = getattr(bp, 'decorator', None)
        if dec is None:
            dec = getattr(Blueprint, 'decorator', None)
        if dec is None:
            return None
        if hasattr(dec, '__get__'):
            return dec.__get__(bp, Blueprint)
        else:
            return dec

    def test_decorator_calls_add_app_template_global_and_returns_function(self):
        bp = Blueprint(name="bp_decorator", import_name=__name__)
        dec = self._get_decorator(bp)
        if dec is None:
            self.skipTest("Blueprint.decorator not available")

        calls = {}

        def fake_add_app_template_global(self_ref, f, name=None):
            calls['f'] = f
            calls['name'] = name

        bp.add_app_template_global = fake_add_app_template_global.__get__(bp, Blueprint)

        @dec
        def some_function():
            return "hello"

        self.assertIs(calls.get('f'), some_function)
        self.assertIn('name', calls)

