import unittest
from unittest.mock import patch
from flask.views import MethodView


class TestDispatchRequest(unittest.TestCase):

    def test_dispatch_calls_get_with_kwargs_and_returns_value(self):
        class MyView(MethodView):
            def get(self, **kwargs):
                return ("GET", kwargs)

        view = MyView()

        class DummyApp:
            def ensure_sync(self, f):
                return f

        with patch('flask.views.request') as mock_request:
            mock_request.method = "GET"
            with patch('flask.views.current_app', new=DummyApp()):
                result = view.dispatch_request(x=1, y=2)

        self.assertEqual(result, ("GET", {'x': 1, 'y': 2}))

    def test_dispatch_handles_head_fallback_to_get(self):
        class MyView(MethodView):
            def get(self, **kwargs):
                return ("GET", kwargs)

        view = MyView()

        class DummyApp:
            def ensure_sync(self, f):
                return f

        with patch('flask.views.request') as mock_request:
            mock_request.method = "HEAD"
            with patch('flask.views.current_app', new=DummyApp()):
                result = view.dispatch_request(a=3)

        self.assertEqual(result, ("GET", {'a': 3}))

    def test_dispatch_raises_when_method_unimplemented(self):
        class NoMethodView(MethodView):
            pass

        view = NoMethodView()

        class DummyApp:
            def ensure_sync(self, f):
                return f

        with patch('flask.views.request') as mock_request:
            mock_request.method = "POST"
            with patch('flask.views.current_app', new=DummyApp()):
                with self.assertRaises(AssertionError) as cm:
                    view.dispatch_request(foo='bar')
        self.assertIn("Unimplemented method 'POST'", str(cm.exception))

    def test_dispatch_raises_on_head_when_get_missing(self):
        class NoGetMethodView(MethodView):
            pass

        view = NoGetMethodView()

        class DummyApp:
            def ensure_sync(self, f):
                return f

        with patch('flask.views.request') as mock_request:
            mock_request.method = "HEAD"
            with patch('flask.views.current_app', new=DummyApp()):
                with self.assertRaises(AssertionError) as cm:
                    view.dispatch_request()
        self.assertIn("Unimplemented method 'HEAD'", str(cm.exception))


if __name__ == '__main__':
    unittest.main()

