from flask.cli import FlaskGroup, ScriptInfo


class TestMakeContext(unittest.TestCase):
    def setUp(self):
        self._old_env = os.environ.get("FLASK_RUN_FROM_CLI")
        if "FLASK_RUN_FROM_CLI" in os.environ:
            del os.environ["FLASK_RUN_FROM_CLI"]

    def tearDown(self):
        if "FLASK_RUN_FROM_CLI" in os.environ and self._old_env is None:
            del os.environ["FLASK_RUN_FROM_CLI"]
        if self._old_env is not None:
            os.environ["FLASK_RUN_FROM_CLI"] = self._old_env

    def test_make_context_sets_env_and_scriptinfo(self):
        def create_app():
            from flask import Flask
            return Flask(__name__)

        g = FlaskGroup(add_default_commands=False, create_app=create_app, load_dotenv=True, set_debug_flag=True)
        ctx = g.make_context(info_name="test", args=[])
        self.assertEqual(os.environ.get("FLASK_RUN_FROM_CLI"), "true")
        self.assertIsInstance(ctx.obj, ScriptInfo)
        self.assertIs(ctx.obj.create_app, create_app)
        self.assertTrue(ctx.obj.load_dotenv_defaults)
        self.assertTrue(ctx.obj.set_debug_flag)

    def test_make_context_preserves_provided_obj(self):
        g = FlaskGroup(add_default_commands=False)
        provided = {"custom": 123}
        ctx = g.make_context(info_name="test", args=[], obj=provided)
