import unittest
from unittest import mock
import click
from flask.cli import AppGroup

class TestDecorator(unittest.TestCase):
    def test_decorator_wraps_with_appcontext_when_wrap_for_ctx_true(self):
        group = AppGroup('test')
        f_called = {'called': False}

        def f():
            f_called['called'] = True

        def fake_with_appcontext(func):
            def wrapper(*args, **kwargs):
                wrapper.used = True
                return func(*args, **kwargs)
            wrapper.used = False
            return wrapper

        import flask.cli as cli_mod
        with mock.patch.object(cli_mod, 'wrap_for_ctx', True), mock.patch.object(cli_mod, 'with_appcontext', fake_with_appcontext):
            cmd = group.decorator(f)
            self.assertIsInstance(cmd, click.Command)
            self.assertTrue(callable(cmd.callback))
            cmd.callback()
            self.assertTrue(getattr(cmd.callback, 'used', False))
            self.assertTrue(f_called['called'])

    def test_decorator_does_not_wrap_when_wrap_for_ctx_false(self):
        group = AppGroup('test')
        f_called = {'called': False}

        def f():
            f_called['called'] = True

        def fail_with_appcontext(_):
            raise AssertionError("with_appcontext should not be called when wrap_for_ctx is False")

        import flask.cli as cli_mod
        with mock.patch.object(cli_mod, 'wrap_for_ctx', False), mock.patch.object(cli_mod, 'with_appcontext', fail_with_appcontext):
            cmd = group.decorator(f)
            self.assertIsInstance(cmd, click.Command)
            self.assertTrue(callable(cmd.callback))
            cmd.callback()
            self.assertTrue(f_called['called'])

if __name__ == '__main__':
    unittest.main()

