import unittest
import flask.cli as cli

class TestDecorator(unittest.TestCase):
    def test_decorator_invokes_function_and_sets_up_context_when_no_app(self):
        # Ensure current_app is falsy to trigger context setup
        cli.current_app = None

        class FakeCtx:
            def __init__(self):
                self.ensure_called = False
                self.load_app_called = False
                self.with_resource_called = False

            def ensure_object(self, cls):
                self.ensure_called = True
                outer = self

                class ScriptInfoLike:
                    def load_app(self):
                        outer.load_app_called = True

                        class AppLike:
                            def app_context(self):
                                class DummyCtxMgr:
                                    def __enter__(self):
                                        return None
                                    def __exit__(self, exc_type, exc, tb):
                                        return False
                                return DummyCtxMgr()
                        return AppLike()

                return ScriptInfoLike()

            def with_resource(self, resource):
                self.with_resource_called = True

            def invoke(self, f, *args, **kwargs):
                # Call the actual function to verify pass-through
                return f(*args, **kwargs)

        # Function to be invoked by decorator
        cli.f = lambda *a, **kw: ('fn_called', a, kw)

        ctx = FakeCtx()
        result = cli.decorator(ctx, 1, 2, a=3)

        self.assertEqual(result, ('fn_called', (1, 2), {'a': 3}))
        self.assertTrue(ctx.ensure_called)
        self.assertTrue(ctx.load_app_called)
        self.assertTrue(ctx.with_resource_called)

    def test_decorator_skips_context_setup_when_app_present(self):
        # Set current_app to a truthy value to skip setup
        cli.current_app = object()

        class FakeCtxNoSetup:
            def __init__(self):
                self.invoked = None

            def invoke(self, f, *args, **kwargs):
                self.invoked = (f, args, kwargs)
                return f(*args, **kwargs)

        cli.f = lambda *a, **kw: ('fn2', a, kw)

        ctx = FakeCtxNoSetup()
        result = cli.decorator(ctx, 'x', y=1)

        self.assertEqual(result, ('fn2', ('x',), {'y': 1}))
        # Ensure that when current_app is truthy, no setup methods are used
        self.assertIsNone(getattr(ctx, 'ensure_called', None))  # ensure_object not called
        self.assertIsNone(getattr(ctx, 'with_resource_called', None))  # with_resource not called

        # Cleanup
        cli.current_app = None

if __name__ == '__main__':
    unittest.main()

