        self.mock_serializer.tag.return_value = 'serialized_value'
        input_value = {'key1': 'value1', 'key2': 'value2'}
        expected_output = {'key1__': 'serialized_value'}

        result = self.tag_dict.to_json(input_value)

        assert result == expected_output
        self.mock_serializer.tag.assert_called_once_with('value1')

    def test_to_json_empty_dict_raises_stop_iteration(self):
        input_value = {}

        with pytest.raises(StopIteration):
            self.tag_dict.to_json(input_value)

    def test_to_json_serializer_missing_tag_method_raises_attribute_error(self):
        del self.tag_dict.serializer.tag
        input_value = {'key1': 'value1'}

        with pytest.raises(AttributeError):
            self.tag_dict.to_json(input_value)

    def test_to_json_serializer_tag_method_fails_raises_attribute_error(self):
        self.mock_serializer.tag.side_effect = AttributeError
        input_value = {'key1': 'value1'}

        with pytest.raises(AttributeError):
            self.tag_dict.to_json(input_value)

