import pytest
from flask.sansio.app import App

class TestAppDecorator:
    def setup_method(self):
        # Initialize the App with default_config to avoid AttributeError
        self.app = App(import_name="test_app")
        self.app.default_config = {}

    def test_decorator_registers_filter(self):
        def sample_filter(value):
            return value.upper()

        # Assume add_template_filter is a method of App that registers the filter
        self.app.add_template_filter = lambda f, name=None: setattr(self.app, f"filter_{name or f.__name__}", f)

        # Use the decorator to register the filter
        decorated_filter = self.app.decorator(sample_filter)

        # Check if the filter is registered correctly
        assert hasattr(self.app, "filter_sample_filter")
        assert self.app.filter_sample_filter == sample_filter

        # Check if the returned function is the same as the original
        assert decorated_filter == sample_filter

    def test_decorator_with_custom_name(self):
        def sample_filter(value):
            return value.lower()

        # Assume add_template_filter is a method of App that registers the filter
        self.app.add_template_filter = lambda f, name=None: setattr(self.app, f"filter_{name or f.__name__}", f)

        # Use the decorator to register the filter with a custom name
        self.app.decorator(sample_filter)
        self.app.add_template_filter(sample_filter, name="custom_filter")

        # Check if the filter is registered with the custom name
        assert hasattr(self.app, "filter_custom_filter")
        assert self.app.filter_custom_filter == sample_filter

    def test_decorator_no_side_effects(self):
        def sample_filter(value):
            return value.capitalize()

        # Assume add_template_filter is a method of App that registers the filter
        self.app.add_template_filter = lambda f, name=None: setattr(self.app, f"filter_{name or f.__name__}", f)

        # Use the decorator to register the filter
        self.app.decorator(sample_filter)

        # Check that the function itself is not modified
        assert sample_filter("test") == "Test"

