import pytest
from flask import Flask
from flask.testing import FlaskCliRunner
from click.testing import Result
from click import Command, Group

class TestFlaskCliRunnerInvoke:

    @pytest.fixture
    def app(self):
        app = Flask(__name__)
        return app

    @pytest.fixture
    def runner(self, app):
        return FlaskCliRunner(app)

    @pytest.fixture
    def command(self):
        return Command('test-command')

    def test_invoke_with_command_and_args(self, runner, command):
        result = runner.invoke(cli=command, args=['--help'])
        assert isinstance(result, Result)
        assert result.exit_code == 0

    def test_invoke_with_default_cli(self, runner):
        result = runner.invoke(args=['--help'])
        assert isinstance(result, Result)
        assert result.exit_code == 0

    def test_invoke_with_invalid_command(self, runner):
        with pytest.raises(ValueError):
            runner.invoke(cli='invalid-command')

    def test_invoke_with_invalid_args(self, runner, command):
        with pytest.raises(TypeError):
            runner.invoke(cli=command, args='not-a-list')

    def test_invoke_with_additional_kwargs(self, runner, command):
        result = runner.invoke(cli=command, args=['--help'], obj={'key': 'value'})
        assert isinstance(result, Result)
        assert result.exit_code == 0

    def test_invoke_without_args(self, runner, command):
        result = runner.invoke(cli=command)
        assert isinstance(result, Result)
        assert result.exit_code == 0

    def test_invoke_with_none_cli(self, runner):
        result = runner.invoke(cli=None, args=['--help'])
        assert isinstance(result, Result)
        assert result.exit_code == 0

