import pytest
import json
from flask.json.provider import DefaultJSONProvider

class TestDefaultJSONProviderDumps:
    def setup_method(self):
        self.provider = DefaultJSONProvider()

    def test_dumps_basic_object(self):
        obj = {"key": "value"}
        result = self.provider.dumps(obj)
        assert result == json.dumps(obj, ensure_ascii=True, sort_keys=True)

    def test_dumps_with_ensure_ascii_false(self):
        obj = {"key": "value"}
        result = self.provider.dumps(obj, ensure_ascii=False)
        assert result == json.dumps(obj, ensure_ascii=False, sort_keys=True)

    def test_dumps_with_sort_keys_false(self):
        obj = {"b": 1, "a": 2}
        result = self.provider.dumps(obj, sort_keys=False)
        assert result == json.dumps(obj, ensure_ascii=True, sort_keys=False)

    def test_dumps_with_non_serializable_object(self):
        class NonSerializable:
            pass

        obj = NonSerializable()
        with pytest.raises(TypeError):
            self.provider.dumps(obj)

    def test_dumps_with_custom_default(self):
        class NonSerializable:
            def __init__(self, value):
                self.value = value

        def custom_default(o):
            if isinstance(o, NonSerializable):
                return {"value": o.value}
            raise TypeError

        obj = NonSerializable("test")
        result = self.provider.dumps(obj, default=custom_default)
        assert result == json.dumps({"value": "test"}, ensure_ascii=True, sort_keys=True)

    def test_dumps_with_compact_true(self):
        obj = {"key": "value"}
        self.provider.compact = True
        result = self.provider.dumps(obj)
        assert result == json.dumps(obj, ensure_ascii=True, sort_keys=True, separators=(',', ':'))

    def test_dumps_with_compact_false(self):
        obj = {"key": "value"}
        self.provider.compact = False
        result = self.provider.dumps(obj)
        assert result == json.dumps(obj, ensure_ascii=True, sort_keys=True, indent=2)

    def test_dumps_with_additional_kwargs(self):
        obj = {"key": "value"}
        result = self.provider.dumps(obj, indent=4)
        assert result == json.dumps(obj, ensure_ascii=True, sort_keys=True, indent=4)

