import pytest
import json
from unittest.mock import Mock, patch
from io import StringIO, BytesIO
from flask.json import load

def test_load_with_valid_json_text_mode():
    json_data = '{"key": "value"}'
    fp = StringIO(json_data)
    result = load(fp)
    assert result == {"key": "value"}

def test_load_with_valid_json_binary_mode():
    json_data = b'{"key": "value"}'
    fp = BytesIO(json_data)
    result = load(fp)
    assert result == {"key": "value"}

def test_load_with_invalid_json():
    json_data = '{"key": "value"'
    fp = StringIO(json_data)
    with pytest.raises(ValueError):
        load(fp)

def test_load_with_flask_context():
    json_data = '{"key": "value"}'
    fp = StringIO(json_data)
    mock_app = Mock()
    mock_app.json.load.return_value = {"key": "value"}

    with patch('flask.json.current_app', mock_app):
        result = load(fp)
        assert result == {"key": "value"}
        mock_app.json.load.assert_called_once_with(fp)

def test_load_without_flask_context():
    json_data = '{"key": "value"}'
    fp = StringIO(json_data)

    with patch('flask.json.current_app', None):
        result = load(fp)
        assert result == {"key": "value"}

def test_load_with_additional_kwargs():
    json_data = '{"key": "value"}'
    fp = StringIO(json_data)
    result = load(fp, parse_int=str)
    assert result == {"key": "value"}

def test_load_with_invalid_file_like_object():
    with pytest.raises(TypeError):
        load("not a file-like object")

