import pytest
from flask.json.tag import TagDict

class DummySerializer:
    def tag(self, v):
        return f"SERIALIZED({v})"

def test_to_json_serializes_first_pair_and_suffix_key():
    td = TagDict()
    td.serializer = DummySerializer()
    value = {"a": 1, "b": 2}
    result = td.to_json(value)
    assert result == {"a__": "SERIALIZED(1)"}
    assert value == {"a": 1, "b": 2}

def test_to_json_raises_stopiteration_on_empty_input():
    td = TagDict()
    td.serializer = DummySerializer()
    with pytest.raises(StopIteration):
        td.to_json({})

def test_to_json_missing_serializer_tag_raises_attribute_error():
    td = TagDict()
    td.serializer = object()  # No 'tag' method
    with pytest.raises(AttributeError):
        td.to_json({"a": 1})

