from flask import Blueprint
import pytest

def _get_globals(bp):
    if hasattr(bp, 'jinja_env') and getattr(bp, 'jinja_env') is not None:
        env = bp.jinja_env
        if hasattr(env, 'globals'):
            return env.globals
    if hasattr(bp, '_template_globals'):
        return bp._template_globals
    return {}

class TestBlueprintAppTemplateGlobal:
    def test_app_template_global_without_name_registers_by_function_name(self):
        bp = Blueprint('bp1', __name__)
        def greet():
            return "hi"
        bp.app_template_global()(greet)
        gdict = _get_globals(bp)
        assert 'greet' in gdict
        assert gdict['greet'] is greet

    def test_app_template_global_with_name_registers_under_custom_name(self):
        bp = Blueprint('bp2', __name__)
        def custom_func():
            return "custom"
        bp.app_template_global('custom_foo')(custom_func)
        gdict = _get_globals(bp)
        assert 'custom_foo' in gdict
        assert gdict['custom_foo'] is custom_func

    def test_app_template_global_direct_function_return(self):
        bp = Blueprint('bp3', __name__)
        def bar():
            return 42
        ret = bp.app_template_global(bar)
        assert ret is bar
        gdict = _get_globals(bp)
        assert 'bar' in gdict
        assert gdict['bar'] is bar

    def test_app_template_global_invalid_name_raises(self):
        bp = Blueprint('bp4', __name__)
        with pytest.raises(ValueError):
            bp.app_template_global('invalid.name')

