    spec = importlib.util.spec_from_file_location('project_flask_views', src_path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def test_view_calls_dispatch_with_kwargs(monkeypatch):
    module = _load_view_module()
    storage = {'kwargs': None}

    class DummyView:
        def __init__(self):
            pass

        def dispatch_request(self, **kwargs):
            storage['kwargs'] = kwargs
            return {"status": "ok", "received": kwargs}

    monkeypatch.setattr(module, 'view_class', DummyView)

    app = Flask(__name__)
    with app.app_context():
        view_func = getattr(module, 'view')
        result = view_func(param1='value1', param2=2)

    assert storage['kwargs'] == {'param1': 'value1', 'param2': 2}
    assert result == {"status": "ok", "received": {'param1': 'value1', 'param2': 2}}


def test_view_raises_attribute_error_when_view_class_missing(monkeypatch):
    module = _load_view_module()
    if hasattr(module, 'view_class'):
        monkeypatch.delattr(module, 'view_class', raising=False)

    app = Flask(__name__)
    with app.app_context():
        view_func = getattr(module, 'view')
        with pytest.raises(AttributeError):
            view_func()


