import pytest
import click
from flask import Flask
from flask.testing import FlaskCliRunner

class TestFlaskCliRunnerInvoke:
    def _create_app(self) -> Flask:
        app = Flask(__name__)

        @app.cli.command("greet")
        def greet():
            click.echo("greet")

        return app

    def test_invoke_uses_app_cli_group(self):
        app = self._create_app()
        runner = FlaskCliRunner(app)
        result = runner.invoke(args=["greet"])
        assert result.exit_code == 0
        assert "greet" in result.output

    def test_invoke_with_explicit_cli_command_object(self):
        @click.group()
        def custom():
            pass

        @custom.command()
        def say_hi():
            click.echo("hi")

        runner = FlaskCliRunner(self._create_app())
        result = runner.invoke(cli=custom, args=["say-hi"])
        assert result.exit_code == 0
        assert "hi" in result.output

    def test_invoke_raises_typeerror_for_invalid_args(self):
        app = self._create_app()
        runner = FlaskCliRunner(app)
        with pytest.raises(TypeError):
            runner.invoke(args=123)

    def test_invoke_passes_obj_to_command(self):
        @click.group()
        def grp():
            pass

        @grp.command()
        @click.pass_context
        def show(ctx):
            if isinstance(ctx.obj, dict) and "custom" in ctx.obj:
                click.echo("custom=" + str(ctx.obj["custom"]))
            else:
                click.echo("noobj")

        runner = FlaskCliRunner(self._create_app())
        result = runner.invoke(cli=grp, args=["show"], obj={"custom": 42})
        assert result.exit_code == 0
        assert "custom=42" in result.output

