import pytest
import click
from flask.cli import AppGroup
from click.testing import CliRunner

def test_decorator_integration_cli_invoke_prints_result(monkeypatch):
    group = AppGroup('test')
    captured = {}

    def fake_command(self, f, *a, **kw):
        captured['f_name'] = getattr(f, '__name__', None)
        captured['args'] = a
        captured['kwargs'] = kw
        return click.Command(name=f.__name__, callback=f)

    monkeypatch.setattr(AppGroup, 'command', fake_command, raising=True)

    def f(x):
        import click
        click.echo(f"result={int(x) * 2}")

    cmd = group.decorator(f)
    runner = CliRunner()
    result = runner.invoke(cmd, ['5'])
    assert result.exit_code == 0
    assert result.output.strip() == 'result=10'
    assert captured['f_name'] == 'f'
    assert captured['args'] == ()
    assert captured['kwargs'] == {}

def test_decorator_passes_args_and_kwargs_to_command(monkeypatch):
    group = AppGroup('test')

    captured = {}

    def fake_command(self, f, *a, **kw):
        if not callable(f):
            raise TypeError("f must be callable")
        captured['args'] = a
        captured['kwargs'] = kw
        return click.Command(name=f.__name__, callback=f)

    monkeypatch.setattr(AppGroup, 'command', fake_command, raising=True)

    def f():
        pass

    cmd = group.decorator(f, 'extra1', 'extra2', option=123)
    assert captured['args'] == ('extra1', 'extra2')
    assert captured['kwargs'] == {'option': 123}

def test_decorator_raises_type_error_for_non_callable(monkeypatch):
    group = AppGroup('test')

    def fake_command(self, f, *a, **kw):
        if not callable(f):
            raise TypeError("f must be callable")
        return click.Command(name=f.__name__, callback=f)

    monkeypatch.setattr(AppGroup, 'command', fake_command, raising=True)

    with pytest.raises(TypeError):
        group.decorator("not a function")

