from flask.json.tag import TaggedJSONSerializer, JSONTag
import pytest


class TestTaggedJSONSerializerRegister:

    def test_register_new_tag_appends_to_order(self):
        """Test that registering a new tag appends it to the order list."""
        serializer = TaggedJSONSerializer()
        initial_order_length = len(serializer.order)
        initial_tags_count = len(serializer.tags)

        class MockTag(JSONTag):
            key = "mock"

            def check(self, value):
                return False

            def to_json(self, value):
                return value

            def to_python(self, value):
                return value

        serializer.register(MockTag)
        assert len(serializer.order) == initial_order_length + 1
        assert len(serializer.tags) == initial_tags_count + 1
        assert serializer.order[-1].__class__ == MockTag
        assert "mock" in serializer.tags

    def test_register_existing_tag_raises_keyerror(self):
        """Test that registering an already registered tag raises KeyError."""
        serializer = TaggedJSONSerializer()

        class MockTag(JSONTag):
            key = "mock"

            def check(self, value):
                return False

            def to_json(self, value):
                return value

            def to_python(self, value):
                return value

        serializer.register(MockTag)
        with pytest.raises(KeyError):
            serializer.register(MockTag)

    def test_register_existing_tag_with_force_overwrites(self):
        """Test that registering an existing tag with force=True overwrites it."""
        serializer = TaggedJSONSerializer()

        class MockTag1(JSONTag):
            key = "mock"

            def check(self, value):
                return False

            def to_json(self, value):
                return value

            def to_python(self, value):
                return value

        class MockTag2(JSONTag):
            key = "mock"

            def check(self, value):
                return False

            def to_json(self, value):
                return value

            def to_python(self, value):
                return value

        serializer.register(MockTag1)
        original_tag = serializer.tags["mock"]
        original_order_len = len(serializer.order)

        serializer.register(MockTag2, force=True)
        assert serializer.tags["mock"].__class__ == MockTag2
        assert len(serializer.order) == original_order_len
        assert serializer.tags["mock"] is not original_tag

    def test_register_with_index_inserts_at_position(self):
        """Test that registering with index inserts the tag at the specified position."""
        serializer = TaggedJSONSerializer()

        class MockTag(JSONTag):
            key = "mock"

            def check(self, value):
                return False

            def to_json(self, value):
                return value

            def to_python(self, value):
                return value

        # Insert at the beginning
        serializer.register(MockTag, index=0)
        assert serializer.order[0].__class__ == MockTag
        assert "mock" in serializer.tags

    def test_register_with_invalid_index_raises_error(self):
        """Test that registering with an invalid index raises IndexError."""
        serializer = TaggedJSONSerializer()

        class MockTag(JSONTag):
            key = "mock"

            def check(self, value):
                return False

            def to_json(self, value):
                return value

            def to_python(self, value):
                return value

        with pytest.raises(IndexError):
            serializer.register(MockTag, index=999)

    def test_register_tag_without_key_attribute_fails(self):
        """Test that registering a tag without a key attribute fails."""
        serializer = TaggedJSONSerializer()

        class MockTag(JSONTag):
            # Missing key attribute
            def check(self, value):
                return False

            def to_json(self, value):
                return value

            def to_python(self, value):
                return value

        with pytest.raises(AttributeError):
            serializer.register(MockTag)

