import pytest
from unittest.mock import Mock, patch
import flask
from flask.views import View

class TestView(View):
    def dispatch_request(self):
        return "test response"

class TestAsView:

    def test_as_view_creates_callable_function(self):
        """Test that as_view returns a callable function"""
        view_func = TestView.as_view('test_view')
        assert callable(view_func)

    def test_as_view_function_has_correct_name(self):
        """Test that the returned function has the correct name"""
        view_func = TestView.as_view('test_view')
        assert view_func.__name__ == 'test_view'

    def test_as_view_with_class_args_and_kwargs(self):
        """Test that as_view properly passes args and kwargs to class constructor"""
        class TestViewWithInit(View):
            def __init__(self, arg1, kwarg1=None):
                self.arg1 = arg1
                self.kwarg1 = kwarg1

            def dispatch_request(self):
                return f"{self.arg1}-{self.kwarg1}"

        view_func = TestViewWithInit.as_view('test_view', 'test_arg', kwarg1='test_kwarg')
        assert callable(view_func)

    def test_as_view_inherits_class_attributes(self):
        """Test that the view function inherits class attributes"""
        TestView.methods = ['GET', 'POST']
        TestView.provide_automatic_options = True

        view_func = TestView.as_view('test_view')
        assert hasattr(view_func, 'methods')
        assert hasattr(view_func, 'provide_automatic_options')
        assert view_func.methods == ['GET', 'POST']
        assert view_func.provide_automatic_options == True

    def test_as_view_with_decorators(self):
        """Test that as_view applies decorators"""
        def test_decorator(f):
            def wrapper(*args, **kwargs):
                return f(*args, **kwargs)
            return wrapper

        TestView.decorators = [test_decorator]
        view_func = TestView.as_view('test_view')
        assert callable(view_func)

    @patch('flask.current_app')
    def test_as_view_with_init_every_request_true(self, mock_current_app):
        """Test behavior when init_every_request is True"""
        mock_app = Mock()
        mock_current_app._get_current_object.return_value = mock_app

        class TestViewEveryRequest(View):
            init_every_request = True

            def dispatch_request(self):
                return "new instance"

        view_func = TestViewEveryRequest.as_view('test_view')
        assert callable(view_func)

    @patch('flask.current_app')
    def test_as_view_with_init_every_request_false(self, mock_current_app):
        """Test behavior when init_every_request is False"""
        mock_app = Mock()
        mock_current_app._get_current_object.return_value = mock_app

        class TestViewSingleInstance(View):
            init_every_request = False

            def dispatch_request(self):
                return "same instance"

        view_func = TestViewSingleInstance.as_view('test_view')
        assert callable(view_func)

    def test_as_view_preserves_class_metadata(self):
        """Test that as_view preserves class metadata"""
        TestView.__module__ = 'test_module'
        TestView.__doc__ = 'Test documentation'

        view_func = TestView.as_view('test_view')
        assert view_func.__module__ == 'test_module'
        assert view_func.__doc__ == 'Test documentation'

