import pytest
from flask.sansio.app import App

class TestAddTemplateFilter:

    def test_add_template_filter_with_name(self):
        app = App(__name__)
        def custom_filter(value):
            return value.upper()

        app.add_template_filter(custom_filter, name="uppercase")

        assert "uppercase" in app.jinja_env.filters
        assert app.jinja_env.filters["uppercase"] is custom_filter

    def test_add_template_filter_without_name(self):
        app = App(__name__)
        def custom_filter(value):
            return value.lower()

        app.add_template_filter(custom_filter)

        assert "custom_filter" in app.jinja_env.filters
        assert app.jinja_env.filters["custom_filter"] is custom_filter

    def test_add_template_filter_callable_required(self):
        app = App(__name__)
        with pytest.raises(TypeError):
            app.add_template_filter("not_a_function")

    def test_add_template_filter_replaces_existing(self):
        app = App(__name__)
        def first_filter(value):
            return value + "1"

        def second_filter(value):
            return value + "2"

        app.add_template_filter(first_filter, name="test_filter")
        app.add_template_filter(second_filter, name="test_filter")

        assert app.jinja_env.filters["test_filter"] is second_filter

    def test_add_template_filter_with_lambda(self):
        app = App(__name__)
        lambda_filter = lambda x: x[::-1]  # reverse string

        app.add_template_filter(lambda_filter, name="reverse")

        assert "reverse" in app.jinja_env.filters
        assert app.jinja_env.filters["reverse"] is lambda_filter

    def test_add_template_filter_none_name_uses_function_name(self):
        app = App(__name__)
        def my_custom_filter(text):
            return text.strip()

        app.add_template_filter(my_custom_filter, name=None)

        assert "my_custom_filter" in app.jinja_env.filters
        assert app.jinja_env.filters["my_custom_filter"] is my_custom_filter

