        assert response.status_code == 200

    def test_open_with_custom_headers(self, client):
        response = client.open('/', headers={'X-Custom': 'value'})
        assert response.status_code == 200

    def test_open_multiple_requests_context_isolation(self, client):
        response1 = client.open('/')
        response2 = client.open('/')
        assert response1.status_code == 200
        assert response2.status_code == 200

