import unittest
from unittest.mock import Mock
import sys
import os

# Add the path to import the tag module
sys.path.insert(0, os.path.abspath(os.path.join(os.path.dirname(__file__), '..', '..', '..')))

from flask.json.tag import TagDict

class TestTagDictCheck(unittest.TestCase):

    def setUp(self):
        """Set up test fixtures"""
        # Create a mock serializer with tags
        self.mock_serializer = Mock()
        self.mock_serializer.tags = {"key1", "key2", "key3"}

        # Create TagDict instance
        self.tag_dict = TagDict()
        self.tag_dict.serializer = self.mock_serializer

    def test_valid_dict_with_single_existing_key(self):
        """Test with a valid dictionary containing one key that exists in tags"""
        value = {"key1": "some_value"}
        result = self.tag_dict.check(value)
        self.assertTrue(result)

    def test_valid_dict_with_single_non_existing_key(self):
        """Test with a dictionary containing one key that does not exist in tags"""
        value = {"nonexistent_key": "some_value"}
        result = self.tag_dict.check(value)
        self.assertFalse(result)

    def test_empty_dict(self):
        """Test with an empty dictionary"""
        value = {}
        result = self.tag_dict.check(value)
        self.assertFalse(result)

    def test_dict_with_multiple_keys(self):
        """Test with a dictionary containing multiple keys"""
        value = {"key1": "value1", "key2": "value2"}
        result = self.tag_dict.check(value)
        self.assertFalse(result)

    def test_none_value(self):
        """Test with None as value"""
        value = None
        result = self.tag_dict.check(value)
        self.assertFalse(result)

    def test_non_dict_value(self):
        """Test with a non-dictionary value"""
        values = ["string", 123, [], set(), tuple()]
        for value in values:
            with self.subTest(value=value):
                result = self.tag_dict.check(value)
                self.assertFalse(result)

    def test_dict_with_nested_structure(self):
        """Test with a dictionary containing nested structures"""
        value = {"key1": {"nested": "value"}}
        result = self.tag_dict.check(value)
        self.assertTrue(result)

    def test_empty_serializer_tags(self):
        """Test when serializer has no tags"""
        self.mock_serializer.tags = set()
        value = {"key1": "some_value"}
        result = self.tag_dict.check(value)
        self.assertFalse(result)

    def test_dict_with_numeric_key(self):
        """Test with a dictionary having numeric key"""
        value = {123: "some_value"}
        result = self.tag_dict.check(value)
        self.assertFalse(result)

if __name__ == '__main__':
    unittest.main()

