import unittest
from unittest.mock import Mock, patch, MagicMock
import flask
from flask.views import View

class TestAsView(unittest.TestCase):

    def setUp(self):
        self.app = flask.Flask(__name__)

    def test_as_view_creates_callable_function(self):
        """Test that as_view returns a callable function"""

        class MyView(View):
            def dispatch_request(self):
                return "test"

        with self.app.test_request_context():
            view_func = MyView.as_view('my_view')
            self.assertTrue(callable(view_func))
            self.assertEqual(view_func.__name__, 'my_view')

    def test_as_view_with_init_every_request_true(self):
        """Test as_view behavior when init_every_request is True"""

        class MyView(View):
            init_every_request = True

            def __init__(self, arg1, arg2=None):
                self.arg1 = arg1
                self.arg2 = arg2

            def dispatch_request(self):
                return f"{self.arg1}-{self.arg2}"

        with self.app.test_request_context():
            view_func = MyView.as_view('my_view', 'test_arg', arg2='test_kwarg')
            # Should create new instance on each call
            result = view_func()
            self.assertEqual(result, "test_arg-test_kwarg")

    def test_as_view_with_init_every_request_false(self):
        """Test as_view behavior when init_every_request is False"""

        class MyView(View):
            init_every_request = False

            def __init__(self, arg1, arg2=None):
                self.arg1 = arg1
                self.arg2 = arg2

            def dispatch_request(self):
                return f"{self.arg1}-{self.arg2}"

        with self.app.test_request_context():
            view_func = MyView.as_view('my_view', 'test_arg', arg2='test_kwarg')
            # Should reuse same instance
            result = view_func()
            self.assertEqual(result, "test_arg-test_kwarg")

    def test_as_view_with_decorators(self):
        """Test that as_view applies decorators correctly"""

        def my_decorator(f):
            def wrapper(*args, **kwargs):
                return f"decorated-{f(*args, **kwargs)}"
            return wrapper

        class MyView(View):
            decorators = [my_decorator]

            def dispatch_request(self):
                return "test"

        with self.app.test_request_context():
            view_func = MyView.as_view('my_view')
            result = view_func()
            self.assertEqual(result, "decorated-test")

    def test_as_view_preserves_class_attributes(self):
        """Test that as_view preserves class attributes like methods and provide_automatic_options"""

        class MyView(View):
            methods = ['GET', 'POST']
            provide_automatic_options = False

            def dispatch_request(self):
                return "test"

        with self.app.test_request_context():
            view_func = MyView.as_view('my_view')
            self.assertEqual(view_func.methods, ['GET', 'POST'])
            self.assertEqual(view_func.provide_automatic_options, False)

    def test_as_view_with_multiple_decorators(self):
        """Test as_view with multiple decorators applied in correct order"""

        def decorator1(f):
            def wrapper(*args, **kwargs):
                return f"d1-{f(*args, **kwargs)}"
            return wrapper

        def decorator2(f):
            def wrapper(*args, **kwargs):
                return f"d2-{f(*args, **kwargs)}"
            return wrapper

        class MyView(View):
            decorators = [decorator1, decorator2]

            def dispatch_request(self):
                return "test"

        with self.app.test_request_context():
            view_func = MyView.as_view('my_view')
            result = view_func()
            # Decorators should be applied in reverse order (last first)
            self.assertEqual(result, "d1-d2-test")

    def test_as_view_inherits_class_docstring_and_module(self):
        """Test that as_view preserves docstring and module information"""

        class MyView(View):
            """Test view docstring"""

            def dispatch_request(self):
                return "test"

        with self.app.test_request_context():
            view_func = MyView.as_view('my_view')
            self.assertEqual(view_func.__doc__, "Test view docstring")
            self.assertEqual(view_func.__module__, MyView.__module__)

    @patch('flask.views.current_app')
    def test_as_view_with_current_app_context(self, mock_current_app):
        """Test as_view works with current_app context"""

        mock_app = Mock()
        mock_current_app._get_current_object.return_value = mock_app

        class MyView(View):
            def dispatch_request(self):
                return "test"

        with self.app.test_request_context():
            view_func = MyView.as_view('my_view')
            result = view_func()
            self.assertEqual(result, "test")

    def test_as_view_with_no_arguments(self):
        """Test as_view works with no additional arguments"""

        class MyView(View):
            def dispatch_request(self):
                return "no args test"

        with self.app.test_request_context():
            view_func = MyView.as_view('my_view')
            result = view_func()
            self.assertEqual(result, "no args test")

if __name__ == '__main__':
    unittest.main()

import unittest
from unittest.mock import Mock, patch
from flask.views import MethodView
from flask import request, current_app


class TestDispatchRequest(unittest.TestCase):

    def setUp(self):
        self.method_view = MethodView()
        self.method_view.get = Mock(return_value="GET response")
        self.method_view.post = Mock(return_value="POST response")
        self.method_view.put = Mock(return_value="PUT response")
        self.method_view.delete = Mock(return_value="DELETE response")

    @patch('flask.views.request')
    def test_get_request_dispatch(self, mock_request):
        mock_request.method = 'GET'
        response = self.method_view.dispatch_request()
        self.method_view.get.assert_called_once()
        self.assertEqual(response, "GET response")

    @patch('flask.views.request')
    def test_post_request_dispatch(self, mock_request):
        mock_request.method = 'POST'
        response = self.method_view.dispatch_request()
        self.method_view.post.assert_called_once()
        self.assertEqual(response, "POST response")

    @patch('flask.views.request')
    def test_put_request_dispatch(self, mock_request):
        mock_request.method = 'PUT'
        response = self.method_view.dispatch_request()
        self.method_view.put.assert_called_once()
        self.assertEqual(response, "PUT response")

    @patch('flask.views.request')
    def test_delete_request_dispatch(self, mock_request):
        mock_request.method = 'DELETE'
        response = self.method_view.dispatch_request()
        self.method_view.delete.assert_called_once()
        self.assertEqual(response, "DELETE response")

    @patch('flask.views.request')
    def test_head_request_fallback_to_get(self, mock_request):
        mock_request.method = 'HEAD'
        self.method_view.head = None
        response = self.method_view.dispatch_request()
        self.method_view.get.assert_called_once()
        self.assertEqual(response, "GET response")

    @patch('flask.views.request')
    def test_head_request_with_head_handler(self, mock_request):
        mock_request.method = 'HEAD'
        self.method_view.head = Mock(return_value="HEAD response")
        response = self.method_view.dispatch_request()
        self.method_view.head.assert_called_once()
        self.assertEqual(response, "HEAD response")

    @patch('flask.views.request')
    def test_method_not_allowed_raises_assertion_error(self, mock_request):
        mock_request.method = 'PATCH'
        self.method_view.patch = None
        with self.assertRaises(AssertionError):
            self.method_view.dispatch_request()

    @patch('flask.views.request')
    def test_dispatch_with_kwargs(self, mock_request):
        mock_request.method = 'GET'
        kwargs = {'id': 123, 'name': 'test'}
        self.method_view.get.return_value = "GET response with kwargs"
        response = self.method_view.dispatch_request(**kwargs)
        self.method_view.get.assert_called_once_with(**kwargs)
        self.assertEqual(response, "GET response with kwargs")

    @patch('flask.views.request')
    def test_head_fallback_to_get_with_kwargs(self, mock_request):
        mock_request.method = 'HEAD'
        self.method_view.head = None
        kwargs = {'id': 456}
        response = self.method_view.dispatch_request(**kwargs)
        self.method_view.get.assert_called_once_with(**kwargs)
        self.assertEqual(response, "GET response")


if __name__ == '__main__':
    unittest.main()

