import unittest
import json
from unittest.mock import patch, MagicMock
from flask.json.provider import DefaultJSONProvider


class TestDefaultJSONProviderDumps(unittest.TestCase):

    def setUp(self):
        self.provider = DefaultJSONProvider(app=MagicMock())

    def test_basic_serialization(self):
        obj = {"key": "value"}
        result = self.provider.dumps(obj)
        expected = '{"key": "value"}'
        self.assertEqual(result, expected)

    def test_serialization_with_custom_kwargs(self):
        obj = {"key": "value"}
        result = self.provider.dumps(obj, indent=2)
        # Should respect custom indent while keeping other defaults
        self.assertIn('\n  ', result)

    def test_serialization_with_non_ascii_characters(self):
        obj = {"key": "café"}
        result = self.provider.dumps(obj)
        # With ensure_ascii=True (default), non-ASCII chars should be escaped
        self.assertIn('\\u00e9', result)

    def test_serialization_with_ensure_ascii_false(self):
        obj = {"key": "café"}
        result = self.provider.dumps(obj, ensure_ascii=False)
        # Should preserve the actual character
        self.assertIn('café', result)

    def test_sort_keys_functionality(self):
        obj = {"z_key": 1, "a_key": 2}
        result = self.provider.dumps(obj)
        # Keys should be sorted due to sort_keys=True default
        expected_order = ['"a_key"', '"z_key"']
        result_keys = list(json.loads(result).keys())
        self.assertEqual(result_keys, ["a_key", "z_key"])

    def test_compact_formatting(self):
        self.provider.compact = True
        obj = {"key1": "value1", "key2": "value2"}
        result = self.provider.dumps(obj)
        # Should minimize whitespace
        self.assertNotIn(' ', result.replace('{}', ''))

    def test_default_handler_called_for_non_serializable_object(self):
        class CustomObject:
            pass

        obj = {"custom": CustomObject()}

        # Mock the default method to return a serializable value
        with patch.object(self.provider, 'default', return_value="converted") as mock_default:
            result = self.provider.dumps(obj)
            mock_default.assert_called_once()
            self.assertIn('"custom": "converted"', result)

    def test_override_class_defaults_with_kwargs(self):
        obj = {"z_key": 1, "a_key": 2}
        # Override sort_keys to False
        result = self.provider.dumps(obj, sort_keys=False)
        # Order might not be preserved (implementation-dependent)
        # But we check that it's valid JSON and contains both keys
        parsed = json.loads(result)
        self.assertIn("z_key", parsed)
        self.assertIn("a_key", parsed)

    def test_empty_object_serialization(self):
        obj = {}
        result = self.provider.dumps(obj)
        self.assertEqual(result, '{}')

    def test_nested_object_serialization(self):
        obj = {
            "level1": {
                "level2": {
                    "key": "value"
                }
            }
        }
        result = self.provider.dumps(obj)
        expected = '{"level1": {"level2": {"key": "value"}}}'
        self.assertEqual(result, expected)

    def test_list_serialization(self):
        obj = [1, 2, 3]
        result = self.provider.dumps(obj)
        expected = '[1, 2, 3]'
        self.assertEqual(result, expected)

    def test_none_serialization(self):
        obj = None
        result = self.provider.dumps(obj)
        expected = 'null'
        self.assertEqual(result, expected)

    def test_number_serialization(self):
        obj = {"int": 42, "float": 3.14}
        result = self.provider.dumps(obj)
        # Numbers should be serialized without quotes
        self.assertIn('"int": 42', result)
        self.assertIn('"float": 3.14', result)

    def test_boolean_serialization(self):
        obj = {"true_val": True, "false_val": False}
        result = self.provider.dumps(obj)
        # Booleans should be lowercase
        self.assertIn('"true_val": true', result)
        self.assertIn('"false_val": false', result)


if __name__ == '__main__':
    unittest.main()

