import unittest
from unittest.mock import Mock, patch
import flask
from flask import Flask
from flask.views import View


class TestViewFunction(unittest.TestCase):

    def setUp(self):
        self.app = Flask(__name__)
        self.app.config['TESTING'] = True

    @patch('flask.views.current_app')
    def test_view_function_basic_call(self, mock_current_app):
        # Arrange
        class TestView(View):
            def dispatch_request(self, **kwargs):
                return "test response"

        # Create a view function similar to how Flask does it internally
        def view_func(**kwargs):
            self_instance = view_func.view_class(*view_func.__dict__.get('class_args', []), 
                                               **view_func.__dict__.get('class_kwargs', {}))
            return flask.current_app.ensure_sync(self_instance.dispatch_request)(**kwargs)

        view_func.view_class = TestView
        view_func.class_args = []
        view_func.class_kwargs = {}

        # Setup mock for current_app.ensure_sync
        mock_sync_func = Mock(return_value="test response")
        mock_current_app.ensure_sync.return_value = mock_sync_func

        # Act
        with self.app.app_context():
            result = view_func(test_param="value")

        # Assert
        mock_current_app.ensure_sync.assert_called_once()
        mock_sync_func.assert_called_once_with(test_param="value")
        self.assertEqual(result, "test response")

    @patch('flask.views.current_app')
    def test_view_function_with_args_and_kwargs(self, mock_current_app):
        # Arrange
        class TestView(View):
            def __init__(self, *args, **kwargs):
                pass

            def dispatch_request(self, **kwargs):
                return f"response with {kwargs}"

        def view_func(**kwargs):
            self_instance = view_func.view_class(*view_func.class_args, 
                                               **view_func.class_kwargs)
            return flask.current_app.ensure_sync(self_instance.dispatch_request)(**kwargs)

        view_func.view_class = TestView
        view_func.class_args = [1, 2, 3]
        view_func.class_kwargs = {'init_param': 'test'}

        mock_sync_func = Mock(return_value="response with {'key': 'value'}")
        mock_current_app.ensure_sync.return_value = mock_sync_func

        # Act
        with self.app.app_context():
            result = view_func(key="value")

        # Assert
        mock_current_app.ensure_sync.assert_called_once()
        mock_sync_func.assert_called_once_with(key="value")
        self.assertEqual(result, "response with {'key': 'value'}")

    @patch('flask.views.current_app')
    def test_view_function_exception_handling(self, mock_current_app):
        # Arrange
        class TestView(View):
            def dispatch_request(self, **kwargs):
                raise ValueError("Test exception")

        def view_func(**kwargs):
            self_instance = view_func.view_class(*view_func.class_args, 
                                               **view_func.class_kwargs)
            return flask.current_app.ensure_sync(self_instance.dispatch_request)(**kwargs)

        view_func.view_class = TestView
        view_func.class_args = []
        view_func.class_kwargs = {}

        mock_sync_func = Mock(side_effect=ValueError("Test exception"))
        mock_current_app.ensure_sync.return_value = mock_sync_func

        # Act & Assert
        with self.app.app_context():
            with self.assertRaises(ValueError):
                view_func()

    @patch('flask.views.current_app')
    def test_view_function_multiple_calls(self, mock_current_app):
        # Arrange
        class TestView(View):
            def dispatch_request(self, **kwargs):
                return kwargs.get('data', 'default')

        def view_func(**kwargs):
            self_instance = view_func.view_class(*view_func.class_args, 
                                               **view_func.class_kwargs)
            return flask.current_app.ensure_sync(self_instance.dispatch_request)(**kwargs)

        view_func.view_class = TestView
        view_func.class_args = []
        view_func.class_kwargs = {}

        mock_sync_func = Mock(side_effect=['first', 'second', 'third'])
        mock_current_app.ensure_sync.return_value = mock_sync_func

        # Act
        with self.app.app_context():
            result1 = view_func(data='first')
            result2 = view_func(data='second')
            result3 = view_func(data='third')

        # Assert
        self.assertEqual(mock_current_app.ensure_sync.call_count, 3)
        self.assertEqual(mock_sync_func.call_count, 3)
        self.assertEqual(result1, 'first')
        self.assertEqual(result2, 'second')
        self.assertEqual(result3, 'third')


if __name__ == '__main__':
    unittest.main()

