import unittest
import json
from unittest.mock import patch, MagicMock
from flask.json.provider import DefaultJSONProvider


class TestDefaultJSONProviderDumps(unittest.TestCase):

    def setUp(self):
        self.provider = DefaultJSONProvider(None)

    def test_dumps_with_default_parameters(self):
        obj = {"key": "value"}
        result = self.provider.dumps(obj)
        expected = json.dumps(obj, default=self.provider.default, ensure_ascii=True, sort_keys=True)
        self.assertEqual(result, expected)

    def test_dumps_with_custom_object_using_default_serializer(self):
        class CustomObject:
            def __init__(self, value):
                self.value = value

        obj = {"custom": CustomObject("test")}
        result = self.provider.dumps(obj)
        # The default serializer will convert CustomObject to a string representation
        parsed_result = json.loads(result)
        self.assertIn("custom", parsed_result)
        self.assertIsInstance(parsed_result["custom"], str)

    def test_dumps_overrides_default_parameters(self):
        obj = {"b_key": 1, "a_key": 2}
        # Override sort_keys to False
        result = self.provider.dumps(obj, sort_keys=False)
        expected = json.dumps(obj, default=self.provider.default, ensure_ascii=True, sort_keys=False)
        self.assertEqual(result, expected)

    def test_dumps_with_ensure_ascii_false(self):
        provider = DefaultJSONProvider(None)
        provider.ensure_ascii = False
        obj = {"unicode": "café"}
        result = provider.dumps(obj)
        expected = json.dumps(obj, default=provider.default, ensure_ascii=False, sort_keys=True)
        self.assertEqual(result, expected)

