from unittest.mock import patch, MagicMock
from datetime import timedelta
from flask.blueprints import Blueprint
from flask import current_app


class TestGetSendFileMaxAge(unittest.TestCase):

    def setUp(self):
        # Create a blueprint instance for testing
        self.blueprint = Blueprint('test_bp', __name__)

    @patch('flask.blueprints.current_app')
    def test_returns_none_when_config_is_none(self, mock_current_app):
        # Arrange
        mock_current_app.config = {"SEND_FILE_MAX_AGE_DEFAULT": None}

        # Act
        result = self.blueprint.get_send_file_max_age("test_file.txt")

        # Assert
        self.assertIsNone(result)

    @patch('flask.blueprints.current_app')
    def test_returns_integer_value_directly(self, mock_current_app):
        # Arrange
        expected_value = 3600
        mock_current_app.config = {"SEND_FILE_MAX_AGE_DEFAULT": expected_value}

        # Act
        result = self.blueprint.get_send_file_max_age("test_file.txt")

        # Assert
        self.assertEqual(result, expected_value)

    @patch('flask.blueprints.current_app')
    def test_converts_timedelta_to_seconds(self, mock_current_app):
        # Arrange
        expected_seconds = 7200
        mock_current_app.config = {"SEND_FILE_MAX_AGE_DEFAULT": timedelta(hours=2)}

        # Act
        result = self.blueprint.get_send_file_max_age("test_file.txt")

        # Assert
        self.assertEqual(result, expected_seconds)

    @patch('flask.blueprints.current_app')
    def test_handles_filename_none_case(self, mock_current_app):
        # Arrange
        expected_value = 1800
        mock_current_app.config = {"SEND_FILE_MAX_AGE_DEFAULT": expected_value}

        # Act
        result = self.blueprint.get_send_file_max_age(None)

        # Assert
        self.assertEqual(result, expected_value)

    @patch('flask.blueprints.current_app')
    def test_handles_various_timedelta_values(self, mock_current_app):
        # Arrange
        test_cases = [
            (timedelta(seconds=30), 30),
            (timedelta(minutes=5), 300),
            (timedelta(days=1), 86400),
        ]

        for td_value, expected in test_cases:
            with self.subTest(td_value=td_value):
                mock_current_app.config = {"SEND_FILE_MAX_AGE_DEFAULT": td_value}

                # Act
                result = self.blueprint.get_send_file_max_age("test.txt")

                # Assert
                self.assertEqual(result, expected)


if __name__ == '__main__':
    unittest.main()

