import unittest

from flask.sansio.scaffold import Scaffold


class DummyScaffold(Scaffold):
    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.latest_rule = None

    def add_url_rule(self, rule, endpoint=None, view_func=None, **options):
        self.latest_rule = {
            "rule": rule,
            "endpoint": endpoint,
            "view_func": view_func,
            "options": options,
        }

    def route(self, rule, **options):
        def decorator(f):
            endpoint = options['endpoint']  # Will raise KeyError if missing
            self.add_url_rule(rule, endpoint=endpoint, view_func=f, **options)
            return f
        return decorator


class TestScaffoldDecorator(unittest.TestCase):
