        self.assertEqual(scaf.latest_rule["rule"], "/path")
        self.assertEqual(scaf.latest_rule["endpoint"], "ep")
        self.assertIs(scaf.latest_rule["view_func"], view)

    def test_decorator_missing_endpoint_raises_keyerror(self):
        scaf = DummyScaffold(import_name="test")
