import unittest
from flask import Flask
from flask.views import MethodView

class TestDispatchRequest(unittest.TestCase):

    def test_dispatch_request_calls_get_when_get_defined(self):
        class GetView(MethodView):
            def __init__(self):
                self.kwargs_received = None

            def get(self, **kwargs):
                self.kwargs_received = kwargs
                return ('GET', kwargs)

        app = Flask(__name__)
        with app.test_request_context('/', method='GET'):
            view = GetView()
            result = view.dispatch_request(foo=1, bar=2)
            self.assertEqual(result, ('GET', {'foo': 1, 'bar': 2}))
            self.assertEqual(view.kwargs_received, {'foo': 1, 'bar': 2})

    def test_dispatch_request_head_falls_back_to_get(self):
        class GetView(MethodView):
            def __init__(self):
                self.kwargs_received = None

            def get(self, **kwargs):
                self.kwargs_received = kwargs
                return ('GET', kwargs)

        app = Flask(__name__)
        with app.test_request_context('/', method='HEAD'):
            view = GetView()
            result = view.dispatch_request(a=10)
            self.assertEqual(result, ('GET', {'a': 10}))
            self.assertEqual(view.kwargs_received, {'a': 10})

    def test_dispatch_request_raises_when_no_handler_found(self):
        class EmptyView(MethodView):
            pass

        app = Flask(__name__)
        with app.test_request_context('/', method='HEAD'):
            view = EmptyView()
            with self.assertRaises(AssertionError):
                view.dispatch_request()

    def test_dispatch_request_raises_when_handler_not_callable(self):
        class BadView(MethodView):
            def __init__(self):
                self.get = 123  # non-callable

        app = Flask(__name__)
        with app.test_request_context('/', method='GET'):
            view = BadView()
            with self.assertRaises(AssertionError):
                view.dispatch_request()

    def test_dispatch_request_does_not_mutate_view_state(self):
        class NoMutationView(MethodView):
            def get(self, **kwargs):
                return kwargs

        app = Flask(__name__)
        with app.test_request_context('/', method='GET'):
            view = NoMutationView()
            view.state = 'unchanged'
            result = view.dispatch_request(x=5)
            self.assertEqual(result, {'x': 5})
            self.assertEqual(view.state, 'unchanged')


if __name__ == '__main__':
    unittest.main()

