import unittest
from flask import Flask
import flask.views as views


class TestViewFunction(unittest.TestCase):
    def setUp(self):
        # Preserve original state of module-level view_class if present
        self._had_original_view_class = hasattr(views, 'view_class')
        self._original_view_class = getattr(views, 'view_class', None)
        self.app = Flask(__name__)

    def tearDown(self):
        # Restore original state of module-level view_class
        if self._had_original_view_class:
            setattr(views, 'view_class', self._original_view_class)
        else:
            if hasattr(views, 'view_class'):
                delattr(views, 'view_class')

    def test_view_success_calls_dispatch_and_returns_value(self):
        class DummyView:
            def __init__(self, **kwargs):
                self.init_kwargs = kwargs

            def dispatch_request(self, **kwargs):
                self.dispatch_kwargs = kwargs
                return {
                    'init': self.init_kwargs,
                    'dispatch': self.dispatch_kwargs
                }

        with self.app.app_context():
            views.view_class = DummyView
            result = views.view(x=1, y=2)

        expected = {
            'init': {'x': 1, 'y': 2},
            'dispatch': {'x': 1, 'y': 2}
        }
        self.assertEqual(result, expected)

    def test_view_missing_view_class_attribute_raises_attribute_error(self):
        # Remove view_class if it exists to simulate missing attribute
        if hasattr(views, 'view_class'):
            delattr(views, 'view_class')
        with self.assertRaises(AttributeError):
            views.view()

        # Restore original state if anything existed
        if self._had_original_view_class:
            setattr(views, 'view_class', self._original_view_class)

    def test_view_missing_dispatch_request_attribute_raises_attribute_error(self):
        class NoDispatch:
            def __init__(self, **kwargs):
                pass
            # Note: No dispatch_request method

        with self.app.app_context():
            views.view_class = NoDispatch
            with self.assertRaises(AttributeError):
                views.view()

    def test_view_without_app_context_raises_runtime_error(self):
        class DummyView:
            def __init__(self, **kwargs):
                pass

            def dispatch_request(self, **kwargs):
                return "ok"

        # Do not push app context to simulate missing application context
        views.view_class = DummyView
        with self.assertRaises(RuntimeError):
            views.view(a=1)

    def test_view_raises_type_error_on_incompatible_kwargs(self):
        class BadDispatchView:
            def __init__(self, **kwargs):
                self.received = kwargs

            def dispatch_request(self, **kwargs):
                raise TypeError("incompatible kwargs")

        with self.app.app_context():
            views.view_class = BadDispatchView
            with self.assertRaises(TypeError):
                views.view(invalid=1)


if __name__ == '__main__':
    unittest.main()

