import unittest
import click
from flask import Flask
from flask.testing import FlaskCliRunner

class TestFlaskCliRunnerInvoke(unittest.TestCase):
    def setUp(self):
        self.app = Flask(__name__)

        @self.app.cli.command()
        def hello():
            click.echo("hello")

        @self.app.cli.command()
        @click.pass_context
        def show_obj(ctx):
            click.echo(type(ctx.obj).__name__)

        @self.app.cli.command()
        def separate():
            click.echo("separate")

        self.runner = FlaskCliRunner(self.app)

    def test_invoke_uses_app_cli_by_default(self):
        result = self.runner.invoke(None, ['hello'])
        self.assertEqual(result.exit_code, 0)
        self.assertIn('hello', result.output)

    def test_invoke_uses_provided_cli_command(self):
        @click.command()
        def separate_cmd():
            click.echo("separate-from-other")

        result = self.runner.invoke(separate_cmd, [])
        self.assertEqual(result.exit_code, 0)
        self.assertIn('separate-from-other', result.output)

    def test_invoke_raises_typeerror_for_invalid_args(self):
        with self.assertRaises(TypeError):
            self.runner.invoke(None, 123)

    def test_invoke_invalid_cli_object_raises(self):
        with self.assertRaises(TypeError):
            self.runner.invoke(123, [])

    def test_invoke_obj_type_is_scriptinfo(self):
        result = self.runner.invoke(None, ['show-obj'])
        self.assertEqual(result.exit_code, 0)
        self.assertIn('ScriptInfo', result.output)

    def test_invoke_does_not_modify_app_state(self):
        before = len(self.app.cli.commands)
        _ = self.runner.invoke(None, ['hello'])
        after = len(self.app.cli.commands)
        self.assertEqual(before, after)

