import unittest
from flask.json.provider import DefaultJSONProvider


class TestDumps(unittest.TestCase):
    def setUp(self):
        self.provider = DefaultJSONProvider()

    def test_basic_serialization_sorted_keys(self):
        obj = {'b': 2, 'a': 1}
        result = self.provider.dumps(obj)
        self.assertEqual(result, '{"a": 1, "b": 2}')

    def test_ensure_ascii_escapes_non_ascii(self):
        obj = {'greeting': 'áéí'}
        result = self.provider.dumps(obj)
        self.assertIn('\\u00e1', result)
        self.assertIn('\\u00e9', result)
        self.assertIn('\\u00ed', result)
        self.assertNotIn('á', result)

    def test_non_serializable_raises_type_error(self):
        with self.assertRaises(TypeError):
            self.provider.dumps({1, 2, 3})

    def test_custom_default_handles_sets(self):
        obj = {'numbers': {1, 2}}
        result = self.provider.dumps(obj, default=lambda o: sorted(list(o)))
        self.assertEqual(result, '{"numbers": [1, 2]}')

    def test_override_indent_formatting(self):
        obj = {'a': 1, 'b': 2}
        result = self.provider.dumps(obj, indent=2)
        expected = '{\n  "a": 1,\n  "b": 2\n}'
        self.assertEqual(result, expected)

    def test_override_ensure_ascii_false(self):
        obj = {'greeting': 'áéí'}
        result = self.provider.dumps(obj, ensure_ascii=False)
        self.assertIn('áéí', result)
        self.assertIn('"greeting":', result)

    def test_input_object_unchanged(self):
        obj = {'a': [1, 2, 3]}
        before = obj.copy()
        self.provider.dumps(obj)
        self.assertEqual(obj, before)


if __name__ == '__main__':
    unittest.main()

