import unittest
from flask import Flask, jsonify, redirect, request


class TestOpen(unittest.TestCase):
    def test_open_basic_get(self):
        app = Flask(__name__)

        @app.route('/hello')
        def hello():
            return jsonify({'hello': 'world'})

        client = app.test_client()
        resp = client.open('/hello')
        self.assertEqual(resp.status_code, 200)
        self.assertEqual(resp.get_json(), {'hello': 'world'})

    def test_open_follow_redirects(self):
        app = Flask(__name__)
        from flask import redirect

        @app.route('/redirect')
        def do_redirect():
            return redirect('/final')

        @app.route('/final')
        def final():
            return jsonify({'ok': True})

        client = app.test_client()

        # Do not follow redirects
        resp = client.open('/redirect', follow_redirects=False)
        self.assertIn(resp.status_code, (301, 302))
        # Follow redirects
        resp_followed = client.open('/redirect', follow_redirects=True)
        self.assertEqual(resp_followed.status_code, 200)
        self.assertEqual(resp_followed.get_json(), {'ok': True})

    def test_open_environ_overrides_remote_addr(self):
        app = Flask(__name__)

        @app.route('/addr')
        def addr():
            return jsonify({'addr': request.remote_addr})

        client = app.test_client()
        resp = client.open('/addr', environ_overrides={'REMOTE_ADDR': '1.2.3.4'})
        self.assertEqual(resp.status_code, 200)
        self.assertEqual(resp.get_json(), {'addr': '1.2.3.4'})

    def test_open_post_with_data(self):
        app = Flask(__name__)

        @app.route('/echo', methods=['POST'])
        def echo():
            return jsonify({'user': request.form.get('user')})

        client = app.test_client()
        resp = client.open('/echo', method='POST', data={'user': 'alice'})
        self.assertEqual(resp.status_code, 200)
        self.assertEqual(resp.get_json(), {'user': 'alice'})

    def test_open_invalid_args_raises(self):
        app = Flask(__name__)
        client = app.test_client()

        with self.assertRaises((ValueError, TypeError)):
            client.open(123)  # invalid first argument


if __name__ == '__main__':
    unittest.main()

