import unittest

from flask.cli import AppGroup


class TestDecorator(unittest.TestCase):
    def test_basic_decorator_calls_command_and_passes_function(self):
        group = AppGroup.__new__(AppGroup)
        captured = {}

        def fake_command(*args, **kwargs):
            captured['args'] = args
            captured['kwargs'] = kwargs

            def inner(func):
                captured['registered_func'] = func
                return 'CMD'
            return inner

        group.command = fake_command

        if hasattr(group, 'wrap_for_ctx'):
            delattr(group, 'wrap_for_ctx')

        def sample_function():
            pass

        result = group.decorator(sample_function)
        self.assertEqual(result, 'CMD')
        self.assertIn('registered_func', captured)
        self.assertIs(captured['registered_func'], sample_function)

    def test_wrap_for_ctx_applied_before_registration(self):
        group = AppGroup.__new__(AppGroup)
        wrap_called = {'called': False}
        captured = {}

        def wrap_for_ctx(f):
            wrap_called['called'] = True

            def wrapped(*args, **kwargs):
                return f(*args, **kwargs)

            wrapped.__name__ = 'wrapped_' + getattr(f, '__name__', 'func')
            return wrapped

        group.wrap_for_ctx = wrap_for_ctx

        def fake_command(*args, **kwargs):
            def inner(func):
                captured['registered_func'] = func
                return 'CMD'
            return inner

        group.command = fake_command

        def original_function(x):
            return x

        result = group.decorator(original_function)
        self.assertEqual(result, 'CMD')
        self.assertTrue(wrap_called['called'])
        reg_func = captured['registered_func']
        self.assertIsNot(reg_func, original_function)
        self.assertEqual(reg_func.__name__, 'wrapped_original_function')

    def test_non_callable_raises_typeerror(self):
        group = AppGroup.__new__(AppGroup)
        with self.assertRaises(TypeError):
            group.decorator(123)


if __name__ == '__main__':
    unittest.main()

