import os
import unittest
import click

try:
    from flask.cli import FlaskGroup
except Exception:
    FlaskGroup = None  # type: ignore

try:
    from flask.cli import ScriptInfo
except Exception:
    ScriptInfo = None  # type: ignore


class TestMakeContext(unittest.TestCase):

    @classmethod
    def setUpClass(cls):
        if FlaskGroup is None:
            raise unittest.SkipTest("FlaskGroup is not available in this environment")

    def setUp(self):
        # Normalize environment for tests
        self._orig_env = os.environ.get("FLASK_RUN_FROM_CLI")
        os.environ["FLASK_RUN_FROM_CLI"] = "false"

    def tearDown(self):
        # Restore environment
        if self._orig_env is None:
            if "FLASK_RUN_FROM_CLI" in os.environ:
                del os.environ["FLASK_RUN_FROM_CLI"]
        else:
            os.environ["FLASK_RUN_FROM_CLI"] = self._orig_env

    def test_make_context_creates_context_with_default_obj(self):
        group = FlaskGroup(add_default_commands=False, create_app=None)
        ctx = group.make_context(info_name="test", args=[])
        self.assertIsInstance(ctx, click.Context)
        self.assertEqual(os.environ.get("FLASK_RUN_FROM_CLI"), "true")
        if ScriptInfo is not None:
            self.assertIsInstance(ctx.obj, ScriptInfo)
        else:
            self.assertIsNotNone(ctx.obj)

    def test_make_context_respects_provided_obj(self):
        group = FlaskGroup(add_default_commands=False, create_app=None)
        custom_obj = {"custom": "value"}
        ctx = group.make_context(info_name="test", args=[], obj=custom_obj)
        self.assertIs(ctx.obj, custom_obj)

    def test_make_context_uses_parent_context(self):
        group = FlaskGroup(add_default_commands=False, create_app=None)
        parent = click.Context(group, info_name="parent")
        ctx = group.make_context(info_name="child", args=[], parent=parent)
        self.assertIs(ctx.parent, parent)

    def test_make_context_sets_info_name(self):
        group = FlaskGroup(add_default_commands=False, create_app=None)
        ctx = group.make_context(info_name="custom", args=[])
        self.assertEqual(ctx.info_name, "custom")

