import unittest
from flask.sansio.scaffold import Scaffold

class TestScaffoldUrlDefaults(unittest.TestCase):

    def setUp(self):
        self.scaffold = Scaffold(__name__)

    def test_url_defaults_registers_function(self):
        """Test that url_defaults registers a function correctly."""
        def dummy_func(endpoint, values):
            pass

        result = self.scaffold.url_defaults(dummy_func)

        # Check that the function is appended to the None key (app-wide)
        self.assertIn(dummy_func, self.scaffold.url_default_functions[None])
        # Check that the function is returned
        self.assertEqual(result, dummy_func)

    def test_url_defaults_registers_multiple_functions(self):
        """Test that multiple calls to url_defaults register all functions."""
        def func_a(endpoint, values):
            pass

        def func_b(endpoint, values):
            pass

        self.scaffold.url_defaults(func_a)
        self.scaffold.url_defaults(func_b)

        self.assertIn(func_a, self.scaffold.url_default_functions[None])
        self.assertIn(func_b, self.scaffold.url_default_functions[None])
        self.assertEqual(len(self.scaffold.url_default_functions[None]), 2)

    def test_url_defaults_with_decorator(self):
        """Test using url_defaults as a decorator."""
        @self.scaffold.url_defaults
        def decorated_func(endpoint, values):
            pass

        self.assertIn(decorated_func, self.scaffold.url_default_functions[None])

    def test_url_defaults_state_integrity(self):
        """Test that url_defaults maintains list structure for keys."""
        def func_1(endpoint, values):
            pass

        self.scaffold.url_defaults(func_1)

        # Ensure the structure remains a list
        self.assertIsInstance(self.scaffold.url_default_functions[None], list)

if __name__ == '__main__':
