import unittest
import os
from flask.sansio.blueprints import Blueprint

class TestBlueprintAppTemplateGlobal(unittest.TestCase):

    def setUp(self):
        self.bp = Blueprint('test_bp', __name__)

    def test_app_template_global_as_decorator_without_name(self):
        """Test registration using decorator without providing a custom name."""

        @self.bp.app_template_global
        def my_global_func():
            return "global_result"

        # The registration is deferred. We check the deferred_functions list.
        self.assertEqual(len(self.bp.deferred_functions), 1)

        # Create a mock app to pass to the deferred function
        class MockApp:
            def __init__(self):
                self.globals = {}
                # Blueprint.setup_method often checks for this attribute in Flask internals
                self.first_registration = False

            def add_template_global(self, f, name=None):
                self.globals[name or f.__name__] = f

        app = MockApp()
        deferred_func = self.bp.deferred_functions[0]
        deferred_func(app)

        self.assertIn('my_global_func', app.globals)
        self.assertEqual(app.globals['my_global_func'], my_global_func)

    def test_app_template_global_as_decorator_with_name(self):
        """Test registration using decorator with a custom name."""

        @self.bp.app_template_global('custom_name')
        def another_global_func():
            return "custom_result"

        self.assertEqual(len(self.bp.deferred_functions), 1)

        class MockApp:
            def __init__(self):
                self.globals = {}
                self.first_registration = False

            def add_template_global(self, f, name=None):
                self.globals[name or f.__name__] = f

        app = MockApp()
        deferred_func = self.bp.deferred_functions[0]
        deferred_func(app)

        self.assertIn('custom_name', app.globals)
        self.assertEqual(app.globals['custom_name'], another_global_func)

    def test_app_template_global_direct_call_without_name(self):
        """Test registration via direct call without a custom name."""

        def direct_global():
            return "direct_result"

        # Call as a method passing the function as the first argument
        result = self.bp.app_template_global(direct_global)

        self.assertEqual(result, direct_global)
        self.assertEqual(len(self.bp.deferred_functions), 1)

        class MockApp:
            def __init__(self):
                self.globals = {}
                self.first_registration = False

            def add_template_global(self, f, name=None):
                self.globals[name or f.__name__] = f

        app = MockApp()
        self.bp.deferred_functions[0](app)

        self.assertIn('direct_global', app.globals)

    def test_app_template_global_direct_call_with_name(self):
        """Test registration via direct call with a custom name."""

        def direct_global_named():
            return "direct_named_result"

        # Call as a method: func passed as positional arg, name passed as keyword arg
        result = self.bp.app_template_global(direct_global_named, name='explicit_name')

        self.assertEqual(result, direct_global_named)
        self.assertEqual(len(self.bp.deferred_functions), 1)

        class MockApp:
            def __init__(self):
                self.globals = {}
                self.first_registration = False

            def add_template_global(self, f, name=None):
                self.globals[name or f.__name__] = f

        app = MockApp()
        self.bp.deferred_functions[0](app)

        self.assertIn('explicit_name', app.globals)

    def test_app_template_global_deferred_function_registers_to_app(self):
        """Test that the deferred function correctly invokes app.add_template_global."""

        @self.bp.app_template_global('my_var')
        def helper():
            return 123

        class MockApp:
            def __init__(self):
                self.calls = []
                self.first_registration = False

            def add_template_global(self, f, name=None):
                self.calls.append((f, name))

        app = MockApp()
        deferred_func = self.bp.deferred_functions[0]
        deferred_func(app)

        self.assertEqual(len(app.calls), 1)
        func, name = app.calls[0]
        self.assertEqual(func, helper)
        self.assertEqual(name, 'my_var')

if __name__ == '__main__':
    unittest.main()

