import unittest
import datetime
from flask.json.provider import DefaultJSONProvider

class TestDefaultJSONProviderDumps(unittest.TestCase):

    def test_dumps_simple_dict(self):
        provider = DefaultJSONProvider()
        obj = {"key": "value", "number": 123}
        result = provider.dumps(obj)
        # Default sort_keys=True should apply
        self.assertEqual(result, '{"key": "value", "number": 123}')

    def test_dumps_simple_list(self):
        provider = DefaultJSONProvider()
        obj = [1, 2, 3, "string"]
        result = provider.dumps(obj)
        self.assertEqual(result, '[1, 2, 3, "string"]')

    def test_dumps_with_default_override(self):
        provider = DefaultJSONProvider()
        # A datetime object is not serializable by default
        obj = {"time": datetime.datetime(2023, 1, 1, 12, 0, 0)}

        # Patch the default function locally for this call
        def custom_default(o):
            if isinstance(o, datetime.datetime):
                return o.isoformat()
            raise TypeError(f"Object of type {type(o).__name__} is not JSON serializable")

        result = provider.dumps(obj, default=custom_default)
        self.assertEqual(result, '{"time": "2023-01-01T12:00:00"}')

    def test_dumps_with_sort_keys_override(self):
        provider = DefaultJSONProvider()
        obj = {"z": 1, "a": 2}

        # Override default sort_keys=True to False
        result = provider.dumps(obj, sort_keys=False)
        self.assertEqual(result, '{"z": 1, "a": 2}')

    def test_dumps_with_ensure_ascii_override(self):
        provider = DefaultJSONProvider()
        obj = {"message": "こんにちは"}

        # Override default ensure_ascii=True to False
        result = provider.dumps(obj, ensure_ascii=False)
        self.assertEqual(result, '{"message": "こんにちは"}')

    def test_dumps_indented(self):
        provider = DefaultJSONProvider()
        obj = {"a": 1, "b": 2}
        result = provider.dumps(obj, indent=4)
        expected = '{\n    "a": 1,\n    "b": 2\n}'
        self.assertEqual(result, expected)

    def test_dumps_complex_object_type_error(self):
        provider = DefaultJSONProvider()
        # Creating a custom class that is not serializable
        class CustomObject:
            pass

        obj = CustomObject()

        with self.assertRaises(TypeError):
            provider.dumps(obj)

    def test_dumps_empty_object(self):
        provider = DefaultJSONProvider()
        result = provider.dumps({})
        self.assertEqual(result, '{}')

    def test_dumps_none_value(self):
        provider = DefaultJSONProvider()
        result = provider.dumps(None)
        self.assertEqual(result, 'null')

    def test_dumps_boolean(self):
        provider = DefaultJSONProvider()
        obj = {"active": True, "inactive": False}
        result = provider.dumps(obj)
        self.assertEqual(result, '{"active": true, "inactive": false}')

if __name__ == '__main__':
    unittest.main()

