from flask import Flask, Response
from flask.testing import FlaskClient
from werkzeug.test import Client
from werkzeug.test import EnvironBuilder
from werkzeug.wrappers import Request


class TestFlaskClientOpen(unittest.TestCase):

    def setUp(self):
        self.app = Flask(__name__)
        self.app.config['TESTING'] = True
        self.client = FlaskClient(self.app)

    def test_open_basic_request(self):
        @self.app.route("/")
        def index():
            return "Hello"

        response = self.client.open("/")
        self.assertEqual(response.status_code, 200)
        self.assertEqual(b"Hello", response.data)

    def test_open_with_buffered(self):
        @self.app.route("/")
        def index():
            return "Buffered"

        response = self.client.open("/", buffered=True)
        self.assertTrue(response._buffered)

    def test_open_with_follow_redirects(self):
        @self.app.route("/")
        def index():
            return self.app.redirect("/target")

        @self.app.route("/target")
        def target():
            return "Redirected"

        # By default, follow_redirects is False
        response = self.client.open("/")
        self.assertEqual(response.status_code, 302)

        # Explicitly setting follow_redirects to False
        response = self.client.open("/", follow_redirects=False)
        self.assertEqual(response.status_code, 302)

        # Setting follow_redirects to True
        response = self.client.open("/", follow_redirects=True)
        self.assertEqual(response.status_code, 200)
        self.assertEqual(b"Redirected", response.data)

    def test_open_preserve_context_flag(self):
        @self.app.route("/")
        def index():
            return "Context"

        self.client.preserve_context = True

        # We mock the superclass open to prevent actual request execution if needed
        # but here we just verify the attribute exists and is used by logic
        response = self.client.open("/")
        self.assertEqual(response.status_code, 200)
        # Logic checks: if preserve_context is True, contexts are pushed to _new_contexts
        # Resetting logic happens based on this flag.

    def test_open_context_stack_management(self):
        @self.app.route("/")
        def index():
            return "Stack Test"

        # Ensure context stack is clean initially
        self.assertEqual(len(self.client._new_contexts), 0)

        self.client.preserve_context = True
        self.client.open("/")

        # With preserve_context=True, context should be added to _new_contexts
        self.assertEqual(len(self.client._new_contexts), 1)

        # Cleaning up
        self.client._new_contexts = []
        self.client.preserve_context = False

    def test_open_with_environ_builder(self):
        @self.app.route("/", methods=["POST"])
        def index():
            return "Posted"

        builder = EnvironBuilder(method="POST", data="key=value")
        response = self.client.open(builder)
        self.assertEqual(response.status_code, 200)

    def test_open_with_dict_environ(self):
        @self.app.route("/")
