import pytest
from flask.json.tag import TaggedJSONSerializer, JSONTag, TagDict, TagTuple, TagBytes, TagUUID, TagDateTime, PassDict, PassList
from datetime import datetime
from uuid import uuid4
from markupsafe import Markup


class CustomTag(JSONTag):
    """A custom tag for testing priority and custom types."""

    def __init__(self, serializer):
        super().__init__(serializer)
        self.key = " custom-tag "

    def check(self, value):
        return isinstance(value, CustomType)

    def to_json(self, value):
        return self.tag(value.data)

    def tag(self, value):
        return {self.key: str(value)}


class CustomType:
    """A simple class to be handled by CustomTag."""
    def __init__(self, data):
        self.data = data


class TestTag:
    @pytest.fixture
    def serializer(self):
        """Fixture to provide a fresh serializer instance for each test."""
        return TaggedJSONSerializer()

    def test_tag_dict_default(self, serializer):
        """Test that a standard dictionary is tagged correctly by TagDict."""
        value = {"key": "value"}
        result = serializer.tag(value)
        assert result == {" __dict__ ": value}

    def test_tag_dict_nested(self, serializer):
        """Test tagging of a nested dictionary."""
        value = {"outer": {"inner": "data"}}
        result = serializer.tag(value)
        assert result == {" __dict__ ": {"outer": {"inner": "data"}}}

    def test_tag_tuple_default(self, serializer):
        """Test that a standard tuple is tagged correctly by TagTuple."""
        value = (1, 2, 3)
        result = serializer.tag(value)
        assert result == {" __tuple__ ": [1, 2, 3]}

    def test_tag_tuple_empty(self, serializer):
        """Test tagging of an empty tuple."""
        value = ()
        result = serializer.tag(value)
        assert result == {" __tuple__ ": []}

    def test_tag_bytes_default(self, serializer):
        """Test that bytes are tagged correctly by TagBytes."""
        value = b"hello"
        result = serializer.tag(value)
        assert result == {" __bytes__ ": "aGVsbG8="}

    def test_tag_bytes_empty(self, serializer):
        """Test tagging of empty bytes."""
        value = b""
        result = serializer.tag(value)
        assert result == {" __bytes__ ": ""}

    def test_tag_uuid_default(self, serializer):
        """Test that a UUID is tagged correctly by TagUUID."""
        value = uuid4()
        result = serializer.tag(value)
        assert result == {" __uuid__ ": str(value)}

    def test_tag_datetime_default(self, serializer):
        """Test that a datetime object is tagged correctly by TagDateTime."""
        value = datetime(2023, 1, 1, 12, 0, 0)
        result = serializer.tag(value)
        assert result == {" __datetime__ ": "2023-01-01T12:00:00"}

    def test_tag_passthrough_list(self, serializer):
        """Test that a list is passed through unchanged by PassList."""
        value = [1, 2, 3]
        result = serializer.tag(value)
        assert result is value

    def test_tag_passthrough_string(self, serializer):
        """Test that a string is passed through unchanged (no tag matches)."""
        value = "test string"
        result = serializer.tag(value)
        assert result is value

    def test_tag_passthrough_int(self, serializer):
        """Test that an integer is passed through unchanged (no tag matches)."""
        value = 42
        result = serializer.tag(value)
        assert result is value

    def test_tag_passthrough_none(self, serializer):
        """Test that None is passed through unchanged (no tag matches)."""
        value = None
        result = serializer.tag(value)
        assert result is value

    def test_tag_custom_tag_priority(self, serializer):
        """
        Test that tags are applied in order.
        If a custom tag is registered before TagTuple, it handles tuples.
        """
        # Create a custom tag that checks for tuples
        class PriorityTupleTag(JSONTag):
            def check(self, value):
                return isinstance(value, tuple)

            def to_json(self, value):
                return self.tag(list(value))

            def tag(self, value):
                return {" __priority_tuple__ ": value}

        # Register the custom tag
        serializer.register(PriorityTupleTag)

        # Check that our custom tag handles tuples instead of the default TagTuple
        value = (1, 2, 3)
        result = serializer.tag(value)
        assert result == {" __priority_tuple__ ": [1, 2, 3]}
        assert " __tuple__ " not in result

    def test_tag_unregister_prevents_matching(self, serializer):
        """Test that unregistering a tag prevents it from matching."""
        # Unregister TagTuple
        serializer.unregister(TagTuple)

        value = (1, 2, 3)
        result = serializer.tag(value)

        # Since TagTuple is gone, the tuple should be passed through unchanged
        assert result is value

    def test_tag_no_matching_tags(self, serializer):
        """Test that a value is returned unchanged if no tags match."""
        class UnmatchedObject:
            pass

        value = UnmatchedObject()
        result = serializer.tag(value)
        assert result is value

    def test_tag_complex_nested_structure(self, serializer):
        """Test tagging a complex structure with multiple tagged types."""
        value = {
            "id": uuid4(),
            "data": [1, 2, (3, 4)],
            "meta": b"binary",
            "created": datetime(2023, 5, 10, 10, 30)
        }

        result = serializer.tag(value)

        # The outer dict should be tagged by TagDict
        assert " __dict__ " in result

        inner = result[" __dict__ "]

        # Check UUID
        assert isinstance(inner["id"], dict)
        assert " __uuid__ " in inner["id"]

        # Check list (should be passed through)
        assert isinstance(inner["data"], list)

        # Check Tuple inside list
        assert isinstance(inner["data"][2], dict)
        assert " __tuple__ " in inner["data"][2]
        assert inner["data"][2][" __tuple__ "] == [3, 4]

        # Check Bytes
        assert isinstance(inner["meta"], dict)
        assert " __bytes__ " in inner["meta"]

        # Check DateTime
        assert isinstance(inner["created"], dict)
        assert " __datetime__ " in inner["created"]

    def test_tag_markup_passthrough(self, serializer):
        """Test that Markup objects are handled correctly (usually passthrough or converted)."""
        value = Markup("<b>text</b>")
        result = serializer.tag(value)
        # In standard Flask/TaggedJSONSerializer, Markup is handled by TagMarkup which converts to string
        # If TagMarkup is present, it converts it. If not, it passes through.
        # Based on default_tags, TagMarkup is present. 
        # TagMarkup extends TagTuple logic for check, but wraps string.
        # Result depends on specific implementation in TagMarkup.
        # Assuming TagMarkup converts to string and tags it or returns string.
        # Let's verify it doesn't crash and handles the object.
        assert isinstance(result, (str, dict)) 

    def test_tag_register_new_type(self, serializer):
        """Test registering a new tag for a custom type."""

        class CustomIntTag(JSONTag):
            def check(self, value):
                return isinstance(value, int) and value > 1000

            def to_json(self, value):
                return self.tag(str(value))

            def tag(self, value):
                return {" __large_int__ ": value}

        serializer.register(CustomIntTag)

        # Standard int passes through
        assert serializer.tag(10) == 10

        # Large int gets tagged
        result = serializer.tag(2000)
        assert result == {" __large_int__ ": "2000"}

