            "data": [1, 2, (3, 4)],
            "meta": b"binary",
            "created": datetime(2023, 5, 10, 10, 30)
        }

        result = serializer.tag(value)

        # The outer dict should be passed through by PassDict
        assert result == value
        assert "id" in result

        # Check UUID
        assert isinstance(result["id"], dict)
        assert " u" in result["id"]
        assert result["id"][" u"] == str(uid)

        # Check list (should be passed through)
        assert isinstance(result["data"], list)

        # Check Tuple inside list
        assert isinstance(result["data"][2], dict)
        assert " t" in result["data"][2]
        assert result["data"][2][" t"] == [3, 4]

        # Check Bytes
        assert isinstance(result["meta"], dict)
        assert " b" in result["meta"]
        assert result["meta"][" b"] == "YmluYXJ5"

        # Check DateTime
        assert isinstance(result["created"], dict)
        assert " d" in result["created"]
        assert result["created"][" d"] == "Wed, 10 May 2023 10:30:00 GMT"

    def test_tag_markup_passthrough(self, serializer):
        """Test that Markup objects are handled correctly."""
        value = Markup("<b>text</b>")
        result = serializer.tag(value)
        # TagMarkup converts Markup to string and wraps it in a dict with key ' m'
        assert result == {" m": str(value)}

    def test_tag_register_new_type(self, serializer):
        """Test registering a new tag for a custom type."""

        class CustomIntTag(JSONTag):
            def check(self, value):
                return isinstance(value, int) and value > 1000

            def to_json(self, value):
                return self.tag(value)

            def tag(self, value):
                # Return value directly as per to_json logic handling
                return {" __large_int__ ": value}

        serializer.register(CustomIntTag)

        # Standard int passes through
        assert serializer.tag(10) == 10

        # Large int gets tagged
        result = serializer.tag(2000)
        assert result == {" __large_int__ ": 2000}

