import pytest

def dummy_teardown(exception):
    pass

def another_teardown(exception):
    pass

class TestTeardownAppRequest:
    def test_register_teardown_app_request(self):
        """
        Test that a function can be registered via teardown_app_request
        and is added to the deferred setup functions.
        """
        # Mock the App class and its attributes
        class MockApp:
            def __init__(self):
                self.teardown_request_funcs = {None: []}

        bp = __import__('flask.sansio.blueprints', fromlist=['Blueprint']).Blueprint('test_bp', __name__)
        app = MockApp()

        result = bp.teardown_app_request(dummy_teardown)

        assert result is dummy_teardown
        assert len(bp.deferred_functions) == 1

        # Execute the deferred function to ensure it registers with the app
        bp.deferred_functions[0](app)

        assert dummy_teardown in app.teardown_request_funcs[None]

    def test_multiple_teardowns(self):
        """
        Test registering multiple teardown functions via teardown_app_request.
        """
        class MockApp:
            def __init__(self):
                self.teardown_request_funcs = {None: []}

        bp = __import__('flask.sansio.blueprints', fromlist=['Blueprint']).Blueprint('test_bp', __name__)
        app = MockApp()

        bp.teardown_app_request(dummy_teardown)
        bp.teardown_app_request(another_teardown)

        assert len(bp.deferred_functions) == 2

        # Execute deferred functions
        bp.deferred_functions[0](app)
        bp.deferred_functions[1](app)

        assert dummy_teardown in app.teardown_request_funcs[None]
        assert another_teardown in app.teardown_request_funcs[None]

    def test_decorator_usage(self):
        """
        Test that teardown_app_request can be used as a decorator.
        """
        class MockApp:
            def __init__(self):
                self.teardown_request_funcs = {None: []}

        bp = __import__('flask.sansio.blueprints', fromlist=['Blueprint']).Blueprint('test_bp', __name__)
        app = MockApp()

        @bp.teardown_app_request
        def decorated_teardown(exception):
            pass

        assert decorated_teardown in app.teardown_request_funcs[None] or len(bp.deferred_functions) == 1

        if len(bp.deferred_functions) == 1:
            bp.deferred_functions[0](app)
            assert decorated_teardown in app.teardown_request_funcs[None]

    def test_chaining(self):
        """
        Test that the function returned is the same as the input, allowing chaining.
        """
        bp = __import__('flask.sansio.blueprints', fromlist=['Blueprint']).Blueprint('test_bp', __name__)

        def my_teardown(exception):
            pass

        decorated = bp.teardown_app_request(my_teardown)

        assert decorated is my_teardown

    def test_deferred_execution_correctness(self):
        """
        Test that the deferred function actually assigns the teardown to the app correctly
        when multiple blueprints are involved.
        """
        class MockApp:
            def __init__(self):
                self.teardown_request_funcs = {None: []}

        bp1 = __import__('flask.sansio.blueprints', fromlist=['Blueprint']).Blueprint('bp1', __name__)
        bp2 = __import__('flask.sansio.blueprints', fromlist=['Blueprint']).Blueprint('bp2', __name__)
        app = MockApp()

        bp1.teardown_app_request(dummy_teardown)
        bp2.teardown_app_request(another_teardown)

        # Register only bp1
        for func in bp1.deferred_functions:
            func(app)

        assert dummy_teardown in app.teardown_request_funcs[None]
        assert another_teardown not in app.teardown_request_funcs[None]

