import pytest
from flask import Flask, current_app, request
from flask.views import View
from typing import Any

class TestView:
    """Test class for the flask.views.view function (class-based views dispatch)."""

    def test_basic_dispatch(self, app: Flask):
        """Test that the view function instantiates the class and calls dispatch_request."""
        class MyView(View):
            methods = ['GET']

            def dispatch_request(self) -> str:
                return "Hello World"

        # Attach view_class to the wrapper. 
        # In Flask, this is done via app.add_url_rule which wraps view_func,
        # but here we test the low-level dispatch mechanism.
        def view_func(**kwargs: Any) -> Any:
            return MyView.view(**kwargs)

        with app.test_request_context():
            # Simulate the view_class attachment that happens in routing
            MyView.view_class = MyView 
            rv = view_func()
            assert rv == "Hello World"

    def test_dispatch_with_kwargs(self, app: Flask):
        """Test that kwargs are passed to dispatch_request."""
        class MyView(View):
            methods = ['GET']

            def dispatch_request(self, name: str) -> str:
                return f"Hello {name}"

        def view_func(**kwargs: Any) -> Any:
            return MyView.view(**kwargs)

        with app.test_request_context():
            MyView.view_class = MyView
            rv = view_func(name="Flask")
            assert rv == "Hello Flask"

    def test_current_app_context(self, app: Flask):
        """Test that the view runs within the current_app context."""
        class MyView(View):
            methods = ['GET']

            def dispatch_request(self) -> str:
                return current_app.name

        def view_func(**kwargs: Any) -> Any:
            return MyView.view(**kwargs)

        with app.test_request_context():
            MyView.view_class = MyView
            rv = view_func()
            assert rv == "test" # Default pytest flask app name or similar

    def test_request_context_access(self, app: Flask):
        """Test that request context is accessible inside dispatch_request."""
        class MyView(View):
            methods = ['POST']

            def dispatch_request(self) -> str:
                return request.method

        def view_func(**kwargs: Any) -> Any:
            return MyView.view(**kwargs)

        with app.test_request_context(method='POST'):
            MyView.view_class = MyView
            rv = view_func()
            assert rv == "POST"

    def test_auto_behavior(self, app: Flask):
        """Test instantiation and teardown behavior (no state retained)."""
        call_count = 0

        class MyView(View):
            methods = ['GET']

            def __init__(self) -> None:
                super().__init__()
                self.val = 10

            def dispatch_request(self) -> int:
                nonlocal call_count
                call_count += 1
                return self.val + call_count

        def view_func(**kwargs: Any) -> Any:
            return MyView.view(**kwargs)

        with app.test_request_context():
            MyView.view_class = MyView

            # First call
            rv1 = view_func()
            assert rv1 == 11 # 10 + 1

            # Second call should instantiate a fresh class, call_count is global but self.val resets
            rv2 = view_func()
            assert rv2 == 12 # 10 + 2
            assert call_count == 2

    def test_decorator_application(self, app: Flask):
        """Test that decorators defined on the class are applied."""
        def decorator(f):
            def wrapper(*args, **kwargs):
                return f"Wrapped: " + f(*args, **kwargs)
            return wrapper

        class MyView(View):
            decorators = [decorator]
            methods = ['GET']

            def dispatch_request(self) -> str:
                return "Content"

        def view_func(**kwargs: Any) -> Any:
            return MyView.view(**kwargs)

        with app.test_request_context():
            MyView.view_class = MyView
            rv = view_func()
            assert rv == "Wrapped: Content"

    def test_error_attribute_error_no_view_class(self, app: Flask):
        """Test AttributeError if view_class is missing."""
        class MyView(View):
            pass

        def view_func(**kwargs: Any) -> Any:
            # Intentionally not setting view_class
            return MyView.view(**kwargs)

        with app.test_request_context():
            with pytest.raises(AttributeError):
                view_func()

    def test_error_attribute_error_no_dispatch_request(self, app: Flask):
        """Test AttributeError if the class lacks dispatch_request."""
        class BadView(View):
            pass

        def view_func(**kwargs: Any) -> Any:
            return BadView.view(**kwargs)

        with app.test_request_context():
            BadView.view_class = BadView
            # Flask's view implementation expects dispatch_request
            with pytest.raises(AttributeError):
                view_func()

    def test_error_type_bad_arguments(self, app: Flask):
        """Test TypeError if arguments passed don't match dispatch_request signature."""
        class MyView(View):
            methods = ['GET']

            def dispatch_request(self, required_id: int) -> str:
                return str(required_id)

        def view_func(**kwargs: Any) -> Any:
            return MyView.view(**kwargs)

        with app.test_request_context():
            MyView.view_class = MyView
            # Passing a string instead of int, or missing it
            with pytest.raises(TypeError):
                view_func()

            with pytest.raises(TypeError):
                view_func(required_id="not_an_int")

    def test_subclass_behavior(self, app: Flask):
        """Test that standard inheritance works correctly."""
        class BaseView(View):
            methods = ['GET']

            def dispatch_request(self) -> str:
                return "Base"

        class ChildView(BaseView):
            def dispatch_request(self) -> str:
                return "Child: " + super().dispatch_request()

        def view_func(**kwargs: Any) -> Any:
            return ChildView.view(**kwargs)

        with app.test_request_context():
            ChildView.view_class = ChildView
            rv = view_func()
            assert rv == "Child: Base"

