        """Test that keys are sorted by default when sort_keys is not overridden."""
        obj = {"z": 1, "a": 2, "m": 3}
        result = provider.dumps(obj)
        # JSON keys should be ordered a, m, z
        assert result == '{"a": 2, "m": 3, "z": 1}'

    def test_dumps_sort_keys_overridden_false(self, provider):
        """Test that keys are not sorted when sort_keys is explicitly set to False."""
        obj = {"z": 1, "a": 2, "m": 3}
        result = provider.dumps(obj, sort_keys=False)
        # The order depends on insertion order (Python 3.7+)
        assert result == '{"z": 1, "a": 2, "m": 3}'

