        """Test that ensure_ascii is True by default (escapes unicode)."""
        obj = {"message": "héllo wörld"}
        result = provider.dumps(obj)
        assert r"\u00e9" in result
        assert r"\u00f6" in result

    def test_dumps_ensure_ascii_overridden_false(self, provider):
        """Test that ensure_ascii can be set to False to preserve unicode."""
        obj = {"message": "héllo wörld"}
        result = provider.dumps(obj, ensure_ascii=False)
        assert "héllo" in result
        assert "wörld" in result

    def test_dumps_default_handler_datetime(self, provider):
        """Test that the default handler serializes datetime objects to ISO format."""
        obj = {"created_at": datetime(2023, 1, 1, 12, 0, 0)}
        result = provider.dumps(obj)
        assert '"created_at": "2023-01-01T12:00:00"' in result

    def test_dumps_default_handler_uuid(self, provider):
        """Test that the default handler serializes UUID objects."""
        import uuid
        u = uuid.uuid4()
        obj = {"id": u}
        result = provider.dumps(obj)
        assert f'"id": "{u}"' in result

    def test_dumps_default_handler_non_serializable_raises_typeerror(self, provider):
        """Test that a TypeError is raised for non-serializable objects without a handler."""
        class CustomObject:
            pass

        obj = {"data": CustomObject()}
        # DefaultJSONProvider's _default uses json.JSONEncoder.default behavior which raises TypeError
        # for objects it doesn't know (like our bare CustomObject), wrapping it in a TypeError with a specific message.
        with pytest.raises(TypeError):
            provider.dumps(obj)

    def test_dumps_custom_default_handler_override(self, provider):
        """Test that a custom default function passed in kwargs is used."""
        obj = {"complex": object()}

        def custom_default(o):
            return "custom_serialized"

        result = provider.dumps(obj, default=custom_default)
        assert result == '{"complex": "custom_serialized"}'

    def test_dumps_indent(self, provider):
        """Test that indentation can be applied."""
        obj = {"a": 1, "b": 2}
        result = provider.dumps(obj, indent=4)
        assert result == '{\n    "a": 1,\n    "b": 2\n}'

    def test_dumps_separators(self, provider):
        """Test that separators can be customized."""
        obj = {"a": 1, "b": 2}
        # Compact separators
        result = provider.dumps(obj, separators=(',', ':'))
        assert result == '{"a":1,"b":2}'

    def test_dumps_instance_state_unchanged(self, provider):
        """Test that calling dumps does not modify the provider's instance attributes."""
        original_sort_keys = provider.sort_keys
        original_ensure_ascii = provider.ensure_ascii

        provider.dumps({"a": 1}, sort_keys=False, ensure_ascii=False)

        assert provider.sort_keys == original_sort_keys
        assert provider.ensure_ascii == original_ensure_ascii

    def test_dumps_original_obj_unchanged(self, provider):
        """Test that the input object is not modified during serialization."""
        obj = {"list": [1, 2, 3]}
        original_copy = obj.copy()

        provider.dumps(obj, sort_keys=False)

        assert obj == original_copy

